    #[test]
    fn persian_and_arabic_indic_digits_in_a_code_match() {
        let ed = alice_key();
        // If4x-36FU-omFi with its digits typed on a Persian keyboard ...
        let persian = "If\u{06F4}x-\u{06F3}\u{06F6}FU-omFi";
        assert_eq!(security_check(persian, &ed), Check::Match);
        // ... and as Arabic-Indic digits.
        let arabic = "If\u{0664}x \u{0663}\u{0666}FU omFi";
        assert_eq!(security_check(arabic, &ed), Check::Match);
        assert!(fingerprint_matches(persian, VERIFY_FP));
        // The fold is digits only: case still counts, other digits still differ.
        assert_eq!(
            security_check("if\u{06F4}x-\u{06F3}\u{06F6}fu-omfi", &ed),
            Check::CodeCaseOnly
        );
        assert_eq!(
            security_check("If\u{06F5}x-\u{06F3}\u{06F6}FU-omFi", &ed),
            Check::Mismatch
        );
        assert_eq!(fold_code_digit('\u{06F9}'), '9');
        assert_eq!(fold_code_digit('\u{0660}'), '0');
        assert_eq!(fold_code_digit('x'), 'x');
        // The confirmation code reads them too.
        assert!(confirm_code_matches("K7Q\u{06F4}M", "K7Q4M"));
    }

    /// [`VERIFY_FP`] (If4x-36FU-omFi) with its digits typed as `zero`'s
    /// digits (U+06F0 Persian, U+0660 Arabic-Indic).
    fn verify_fp_with_digits(zero: u32) -> String {
        VERIFY_FP
            .chars()
            .map(|c| match c.to_digit(10) {
                Some(d) => char::from_u32(zero + d).unwrap(),
                None => c,
            })
            .collect()
    }

    /// [`VERIFY_FP`] typed with the keyboard on Persian letters (Persian
    /// digits, Arabic-script letters, the dashes as they are).
    const PERSIAN_KEYBOARD_FP: &str = "\u{0647}\u{0628}\u{06F4}\u{0637}-\u{06F3}\u{06F6}\
                                       \u{0628}\u{0639}-\u{062E}\u{0626}\u{0628}\u{0647}";

    #[test]
    fn persian_digits_match_the_code() {
        let ed = alice_key();
        let typed = verify_fp_with_digits(0x06F0);
        assert_ne!(typed, VERIFY_FP);
        assert_eq!(fold_digits(&typed), VERIFY_FP);
        assert!(fingerprint_matches(&typed, VERIFY_FP));
        assert!(!fingerprint_case_only_mismatch(&typed, VERIFY_FP));
        assert_eq!(security_check(&typed, &ed), Check::Match);
        assert_eq!(parse_verify_choice(&typed, &ed), VerifyChoice::Pin);
        assert_eq!(run_verify_flow(None, &["v", &typed]), Some(true));
        assert_eq!(run_blind_check(None, &[&typed]), Ok(Some(typed.clone())));
        // --verify-fp pins with it.
        let dir = tempfile::tempdir().unwrap();
        add_contact(
            dir.path(),
            &encode_address(&ed),
            &hex::encode(ed),
            "Alice",
            "",
            Some(&typed),
            "",
        )
        .unwrap();
        assert!(load_contacts(dir.path()).unwrap()[0].pinned);
        // The confirmation code and an address read them too.
        assert!(confirm_code_matches("K\u{06F7}Q\u{06F4}M", "K7Q4M"));
        let e = parse_route_edit(
            Some("\u{06F1}\u{06F9}\u{06F2}.\u{06F1}\u{06F6}\u{06F8}.1.31:\u{06F7}\u{06F4}\u{06F2}\u{06F0}"),
            Some("203.0.113.\u{06F7}:7422"),
            &[],
        )
        .unwrap();
        assert_eq!(e.lan.as_deref(), Some("192.168.1.31:7420"));
        assert_eq!(e.internet.as_deref(), Some("203.0.113.7:7422"));
    }

    #[test]
    fn arabic_indic_digits_match() {
        let ed = alice_key();
        let typed = verify_fp_with_digits(0x0660);
        assert_ne!(typed, VERIFY_FP);
        assert_eq!(fold_digits(&typed), VERIFY_FP);
        assert!(fingerprint_matches(&typed, VERIFY_FP));
        assert_eq!(security_check(&typed, &ed), Check::Match);
        assert_eq!(run_verify_flow(None, &["v", &typed]), Some(true));
        assert!(confirm_code_matches("K\u{0667}Q\u{0664}M", "K7Q4M"));
        // Both kinds in one code.
        let mixed: String = VERIFY_FP
            .chars()
            .enumerate()
            .map(|(i, c)| {
                let zero = if i % 2 == 0 { 0x0660 } else { 0x06F0 };
                c.to_digit(10)
                    .map_or(c, |d| char::from_u32(zero + d).unwrap())
            })
            .collect();
        assert_eq!(security_check(&mixed, &ed), Check::Match);
        let e = parse_route_edit(
            Some("10.0.0.\u{0662}:\u{0667}\u{0664}\u{0662}\u{0660}"),
            None,
            &[],
        )
        .unwrap();
        assert_eq!(e.lan.as_deref(), Some("10.0.0.2:7420"));
    }

    #[test]
    fn case_still_matters_after_folding() {
        let ed = alice_key();
        for zero in [0x06F0, 0x0660] {
            let lower = verify_fp_with_digits(zero).to_lowercase();
            assert!(!fingerprint_matches(&lower, VERIFY_FP), "{lower}");
            assert!(fingerprint_case_only_mismatch(&lower, VERIFY_FP), "{lower}");
            assert_eq!(security_check(&lower, &ed), Check::CodeCaseOnly);
            assert_eq!(parse_verify_choice(&lower, &ed), VerifyChoice::Abort);
            assert_eq!(run_verify_flow(None, &["v", &lower]), None);
        }
        // The confirmation code ignores case as before: its alphabet has no
        // lower-case letters.
        assert!(confirm_code_matches("k\u{06F7}q\u{06F4}m", "K7Q4M"));
    }

    #[test]
    fn fold_never_turns_a_mismatch_into_a_match() {
        let ed = alice_key();
        // Every digit of the code typed as every Persian and Arabic-Indic
        // digit: a match only where it is the same digit.
        for (i, c) in VERIFY_FP.char_indices() {
            let Some(want) = c.to_digit(10) else {
                continue;
            };
            for zero in [0x06F0, 0x0660] {
                for d in 0..10 {
                    let typed = format!(
                        "{}{}{}",
                        &VERIFY_FP[..i],
                        char::from_u32(zero + d).unwrap(),
                        &VERIFY_FP[i + 1..]
                    );
                    let same = d == want;
                    assert_eq!(fingerprint_matches(&typed, VERIFY_FP), same, "{typed}");
                    assert_eq!(security_check(&typed, &ed) == Check::Match, same, "{typed}");
                }
            }
        }
        // Folding maps one character to one character, and changes only the
        // 20 digits, each to its own ASCII digit: no letter appears, so no
        // other text can start to match.
        for c in (0..=0xFFFF).filter_map(char::from_u32) {
            let folded = fold_digits(&c.to_string());
            let mut chars = folded.chars();
            let f = chars.next().unwrap();
            assert!(chars.next().is_none(), "{c:?}");
            let zero = match c {
                '\u{06F0}'..='\u{06F9}' => 0x06F0,
                '\u{0660}'..='\u{0669}' => 0x0660,
                _ => {
                    assert_eq!(f, c);
                    continue;
                }
            };
            assert_eq!(f.to_digit(10), Some(u32::from(c) - zero), "{c:?}");
        }
        // A wrong code stays wrong with any digits.
        let wrong = "If\u{06F5}x-\u{06F3}\u{06F6}FU-omFi";
        assert_eq!(security_check(wrong, &ed), Check::Mismatch);
        assert!(!confirm_code_matches("K\u{06F7}Q\u{06F5}M", "K7Q4M"));
    }

    #[test]
    fn persian_letters_get_the_keyboard_hint_not_the_attack_warning() {
        let ed = alice_key();
        let typed = PERSIAN_KEYBOARD_FP;
        assert!(code_has_non_latin_letters(typed));
        assert_eq!(security_check(typed, &ed), Check::Mismatch);
        let said = security_check_text(typed, Check::Mismatch, "Alice");
        assert_eq!(said, CODE_KEYBOARD_HINT);
        assert!(!said.contains("swapped"), "{said}");
        // A wrong code in Latin letters still gets the warning.
        assert!(
            security_check_text("AAAA-BBBB-CCCC", Check::Mismatch, "Alice").contains("swapped")
        );
        // Which characters are letters of another script: every range, no
        // digit it folds, nothing Latin or of another alphabet.
        for c in [
            '\u{0600}', '\u{0628}', '\u{065F}', '\u{066A}', '\u{06AF}', '\u{06CC}', '\u{06EF}',
            '\u{06FA}', '\u{06FF}', '\u{0750}', '\u{077F}', '\u{08A0}', '\u{08FF}', '\u{FB50}',
            '\u{FDFF}', '\u{FE70}', '\u{FEFF}',
        ] {
            assert!(code_has_non_latin_letters(&format!("If4x{c}")), "{c:?}");
        }
        for c in ('\u{06F0}'..='\u{06F9}').chain('\u{0660}'..='\u{0669}') {
            assert!(!code_has_non_latin_letters(&c.to_string()), "{c:?}");
        }
        for text in [
            VERIFY_FP,
            "",
            "K7Q4M",
            "br\u{00E9}ad",
            "\u{0416}",
            "\u{05D0}",
        ] {
            assert!(!code_has_non_latin_letters(text), "{text:?}");
        }

        // --verify-fp: refused with the hint, not "fingerprint mismatch";
        // nothing saved.
        let dir = tempfile::tempdir().unwrap();
        let err = add_contact(
            dir.path(),
            &encode_address(&ed),
            &hex::encode(ed),
            "Alice",
            "",
            Some(typed),
            "",
        )
        .unwrap_err();
        assert!(err.contains(CODE_KEYBOARD_HINT), "{err}");
        assert!(!err.contains("fingerprint mismatch"), "{err}");
        assert!(load_contacts(dir.path()).unwrap().is_empty());

        // The guided add: the hint, and the code may be typed again (up to
        // MAX_WORDS_ENTRIES entries in all).
        assert_eq!(run_verify_flow(None, &["v", typed, VERIFY_FP]), Some(true));
        assert_eq!(
            run_verify_flow(None, &["v", typed, typed, VERIFY_FP]),
            Some(true)
        );
        assert_eq!(
            run_verify_flow(None, &["v", typed, typed, typed, VERIFY_FP]),
            None
        );
        // A wrong Latin code still aborts at once.
        assert_eq!(
            run_verify_flow(None, &["v", "AAAA-BBBB-CCCC", VERIFY_FP]),
            None
        );
        // `contact verify`: the hint, and the entry still counts toward the
        // stop (its Latin characters were compared).
        assert_eq!(
            run_blind_check(None, &[typed, VERIFY_FP]),
            Ok(Some(VERIFY_FP.into()))
        );
        assert_eq!(
            run_blind_check(None, &[typed, typed, typed, VERIFY_FP]),
            Err(security_stop_text("Alice"))
        );

        // The confirmation code: the hint, and it is asked again; anything
        // else that is not the code still cancels.
        let slip = "\u{0642}7\u{0635}4\u{0645}";
        assert!(code_has_non_latin_letters(slip));
        assert_eq!(
            run_verify_flow(Some("K7Q4M"), &["c", slip, "K7Q4M"]),
            Some(false)
        );
        assert_eq!(
            run_verify_flow(Some("K7Q4M"), &["c", slip, "WRONG", "K7Q4M"]),
            None
        );
        assert_eq!(
            run_verify_flow(Some("K7Q4M"), &["c", slip, slip, slip, "K7Q4M"]),
            None
        );
        assert_eq!(run_verify_flow(Some("K7Q4M"), &["c", slip]), None);
        assert_eq!(
            run_blind_check(Some("K7Q4M"), &[VERIFY_FP, slip, "k7q4m"]),
            Ok(Some(VERIFY_FP.into()))
        );
        assert_eq!(
            run_blind_check(Some("K7Q4M"), &[VERIFY_FP, slip, slip, slip]),
            Ok(None)
        );
    }

    #[test]
    fn every_security_status_has_its_text_and_none_holds_the_key() {
        let ed = alice_key();
        let alice: Vec<&str> = ALICE_WORDS.split(' ').collect();
        let bob_words = words_text(&ident(0x0b).public_key_bytes());
        let swapped = {
            let mut w = alice.clone();
            w.swap(0, 1);
            w.join(" ")
        };
        let cases: Vec<(String, Check, &str)> = vec![
            (ALICE_WORDS.into(), Check::Match, "They match"),
            (
                bob_words.clone(),
                Check::Mismatch,
                "These are real Raven words, but not Alice's. Do not verify: someone may have \
                 swapped Alice's key, or this is the wrong invite.",
            ),
            (
                "AAAA-BBBB-CCCC".into(),
                Check::Mismatch,
                "The code did not match Alice's key. Do not verify",
            ),
            (
                PERSIAN_KEYBOARD_FP.into(),
                Check::Mismatch,
                "Switch your keyboard to English (Latin) letters for this code. Digits can stay \
                 as they are.",
            ),
            (
                VERIFY_FP.to_ascii_lowercase(),
                Check::CodeCaseOnly,
                "fingerprint did not match: upper/lower case differs",
            ),
            (
                "turtel frog bread wolf paper laptop funnel mango honey wagon".into(),
                Check::Invalid(security_words::ParseError::Unknown { position: 1 }),
                "'turtel' isn't one of Raven's words. Check the spelling, or type its first 3 \
                 letters.",
            ),
            (
                "turtle fr bread wolf paper laptop funnel mango honey wagon".into(),
                Check::Invalid(security_words::ParseError::Ambiguous { position: 2 }),
                "Type at least 3 letters of word 2.",
            ),
            (
                "turtle frog br\u{00E9}ad wolf paper laptop funnel mango honey wagon".into(),
                Check::Invalid(security_words::ParseError::NonLatin { position: 3 }),
                "Type the words with English letters.",
            ),
            (
                alice[..9].join(" "),
                Check::Invalid(security_words::ParseError::WrongCount { count: 9 }),
                "You typed 9 words. A set has 10: ask Alice which one you missed.",
            ),
            (
                format!("{ALICE_WORDS} wagon"),
                Check::Invalid(security_words::ParseError::WrongCount { count: 11 }),
                "You typed 11 words. A set has 10: ask Alice to read them again.",
            ),
            (
                swapped,
                Check::Invalid(security_words::ParseError::BadCheck),
                "These 10 words don't fit together: one may be misheard, or two swapped. Ask \
                 Alice to read them again, slowly.",
            ),
        ];
        for (typed, want, text) in &cases {
            let got = security_check(typed, &ed);
            assert_eq!(got, *want, "{typed}");
            let said = security_check_text(typed, got, "Alice");
            assert!(said.starts_with(text), "{typed}: {said}");
            if got != Check::Match {
                for word in &alice {
                    assert!(!said.contains(word), "{word} in {said}");
                }
                assert!(!said.contains(VERIFY_FP), "{said}");
            }
        }
        assert_eq!(
            security_check_text(
                "",
                Check::Invalid(security_words::ParseError::Empty),
                "Alice"
            ),
            "Type the 10 words Alice reads (or Alice's old code)."
        );
        assert!(security_stop_text("Alice").starts_with("Stop here: Alice stays not verified."));
    }

    #[test]
    fn the_verify_prompt_takes_words_and_retypes_only_what_is_not_words() {
        assert_eq!(run_verify_flow(None, &[ALICE_WORDS]), Some(true));
        assert_eq!(
            run_verify_flow(Some("K7Q4M"), &[ALICE_WORDS, "K7Q4M"]),
            Some(true)
        );
        assert_eq!(run_verify_flow(None, &["v", ALICE_WORDS]), Some(true));
        // A miscount or a misheard word may be typed again; a mismatch aborts.
        let nine = "turtle frog bread wolf paper laptop funnel mango honey";
        assert_eq!(run_verify_flow(None, &["v", nine, ALICE_WORDS]), Some(true));
        assert_eq!(
            run_verify_flow(None, &["v", nine, nine, nine, ALICE_WORDS]),
            None
        );
        let bob_words = words_text(&ident(0x0b).public_key_bytes());
        assert_eq!(run_verify_flow(None, &["v", &bob_words, ALICE_WORDS]), None);
        assert_eq!(run_verify_flow(None, &[&bob_words, "c"]), None);
        // The `words` line of a pasted whoami is a leftover, never the answer.
        let pasted = format!("words         {ALICE_WORDS}");
        assert_eq!(run_verify_flow(None, &["v", &pasted]), None);
    }

    /// `blind_check_flow` for alice over `answers`.
    fn run_blind_check(code: Option<&str>, answers: &[&str]) -> Result<Option<String>, String> {
        let mut it = lines(answers).into_iter();
        blind_check_flow(&alice_key(), "Alice", code, &mut || it.next())
    }

    #[test]
    fn the_blind_check_matches_retries_and_stops() {
        assert_eq!(
            run_blind_check(None, &[ALICE_WORDS]),
            Ok(Some(ALICE_WORDS.into()))
        );
        assert_eq!(
            run_blind_check(None, &[VERIFY_FP]),
            Ok(Some(VERIFY_FP.into()))
        );
        // Enter or EOF cancels.
        assert_eq!(run_blind_check(None, &[""]), Ok(None));
        assert_eq!(run_blind_check(None, &[]), Ok(None));
        // Entries that are not 10 valid words never count against the limit.
        let nine = "turtle frog bread wolf paper laptop funnel mango honey";
        assert_eq!(
            run_blind_check(None, &[nine, nine, nine, nine, ALICE_WORDS]),
            Ok(Some(ALICE_WORDS.into()))
        );
        // Three entries that are not a match: stop, even if the 4th would be.
        let bob_words = words_text(&ident(0x0b).public_key_bytes());
        let stop = run_blind_check(
            None,
            &[&bob_words, "AAAA-BBBB-CCCC", &bob_words, ALICE_WORDS],
        );
        assert_eq!(stop, Err(security_stop_text("Alice")));
        assert_eq!(
            run_blind_check(None, &[&bob_words, &bob_words, ALICE_WORDS]),
            Ok(Some(ALICE_WORDS.into()))
        );
        // At a terminal the save needs the confirmation code.
        assert_eq!(
            run_blind_check(Some("K7Q4M"), &[ALICE_WORDS, "k7q-4m"]),
            Ok(Some(ALICE_WORDS.into()))
        );
        assert_eq!(
            run_blind_check(Some("K7Q4M"), &[ALICE_WORDS, ALICE_WORDS]),
            Ok(None)
        );
        assert_eq!(run_blind_check(Some("K7Q4M"), &[ALICE_WORDS]), Ok(None));
    }

    #[test]
    fn contact_verify_check_pins_and_keeps_name_routes_and_tag() {
        let dir = tempfile::tempdir().unwrap();
        let ed = alice_key();
        let (address, pub_hex) = (encode_address(&ed), hex::encode(ed));
        add_contact_with_routes(
            dir.path(),
            &address,
            &pub_hex,
            "Alice",
            "alice",
            None,
            "192.168.1.20:7420",
            "203.0.113.7:7422",
            None,
        )
        .unwrap();
        // A wrong entry: refused with its text, nothing changes.
        let bob_words = words_text(&ident(0x0b).public_key_bytes());
        let err = cmd_contact_verify(
            dir.path(),
            Some("Alice"),
            None,
            None,
            None,
            Some(&bob_words),
        )
        .unwrap_err();
        assert!(
            err.contains("not Alice's") && err.ends_with("Nothing was saved."),
            "{err}"
        );
        assert!(!load_contacts(dir.path()).unwrap()[0].pinned);
        // Her words: pinned, and everything else kept.
        cmd_contact_verify(
            dir.path(),
            Some("@alice"),
            None,
            None,
            None,
            Some(ALICE_WORDS),
        )
        .unwrap();
        let c = &load_contacts(dir.path()).unwrap()[0];
        assert!(c.pinned);
        assert_eq!(
            (c.petname.as_str(), c.public_tag.as_str()),
            ("Alice", "alice")
        );
        assert_eq!(c.lan_dial, "192.168.1.20:7420");
        assert_eq!(c.internet_dial, "203.0.113.7:7422");
        // The old code works the same way, by any selector.
        cmd_contact_verify(dir.path(), None, None, Some("alice"), None, Some(VERIFY_FP)).unwrap();
        // No contact named: an error, never a silent pick.
        assert!(cmd_contact_verify(dir.path(), None, None, None, None, Some(VERIFY_FP)).is_err());
        assert!(
            cmd_contact_verify(dir.path(), Some("Zed"), None, None, None, Some(VERIFY_FP)).is_err()
        );
    }

    #[test]
    fn a_pasted_whoami_block_with_its_words_line_keeps_the_right_petname() {
        let id = ident(0x0a);
        let words = format!("  words         {}", words_text(&id.public_key_bytes()));
        let fp = format!(
            "  fingerprint   {}",
            device_fingerprint_v1(&id.public_key_bytes())
        );
        let invite = format!("invite        {}", invite_for(&id));
        // Leftover lines of the block before the petname prompt are skipped.
        assert_eq!(
            pick_answer_line(lines(&[&fp, &words, &invite, "Poline"]), AnswerKind::Free),
            "Poline"
        );
        assert_eq!(
            pick_answer_line(lines(&[&words, "Poline"]), AnswerKind::Free),
            "Poline"
        );
    }

    #[test]
    fn eof_is_not_an_answer_but_an_empty_line_is() {
        // Trust decisions use the checked picker: a stream that ends before any
        // answer arrives is None, never "" (which parse_verify_choice aborts
        // and the optional prompts treat as "skip").
        assert_eq!(
            pick_answer_line_checked(Vec::<String>::new(), AnswerKind::Free),
            None
        );
        assert_eq!(
            pick_answer_line_checked(lines(&[""]), AnswerKind::Free),
            Some(String::new())
        );
        let id = ident(0x0a);
        // Only leftover whoami lines, then EOF: still no answer.
        assert_eq!(
            pick_answer_line_checked(lines(&[&invite_for(&id)]), AnswerKind::Free),
            None
        );
        assert_eq!(
            pick_answer_line_checked(lines(&[&invite_for(&id), "c"]), AnswerKind::Free),
            Some("c".to_string())
        );
        // The lenient wrapper folds EOF into an empty answer (optional prompts).
        assert_eq!(pick_answer_line(Vec::<String>::new(), AnswerKind::Free), "");
    }

    #[test]
    fn first_run_identity_needs_a_real_yes() {
        // EOF / closed stdin never creates an identity.
        assert!(!first_run_answer_accepts(None, true));
        assert!(!first_run_answer_accepts(None, false));
        // On a terminal Enter takes the [Y] default; piped input must be explicit.
        assert!(first_run_answer_accepts(Some(""), true));
        assert!(!first_run_answer_accepts(Some(""), false));
        for yes in ["y", "Y", "yes", "YES"] {
            assert!(first_run_answer_accepts(Some(yes), false), "{yes}");
            assert!(first_run_answer_accepts(Some(yes), true), "{yes}");
        }
        for no in ["n", "no", "yep", "sure", "1"] {
            assert!(!first_run_answer_accepts(Some(no), true), "{no}");
            assert!(!first_run_answer_accepts(Some(no), false), "{no}");
        }
    }

    #[test]
    fn leftover_whoami_lines_are_not_answers() {
        let id = ident(0x0a);
        assert!(is_whoami_paste_line(&format!(
            "invite        {}",
            invite_for(&id)
        )));
        assert!(is_whoami_paste_line(&invite_for(&id)));
        assert!(is_whoami_paste_line("fingerprint If4x-36FU-omFi"));
        assert!(is_whoami_paste_line(&format!(
            "pub_hex     {}",
            hex::encode(id.public_key_bytes())
        )));
        assert!(is_whoami_paste_line(&format!(
            "address     {}",
            id.address()
        )));
        // The `words` line, as whoami prints it (indented) or labelled with =.
        let words = words_text(&id.public_key_bytes());
        assert!(is_whoami_paste_line(&format!("  words         {words}")));
        assert!(is_whoami_paste_line(&format!("words={words}")));
        assert!(is_whoami_words_line(&format!("WORDS  {words}")));
        for answer in [
            "",
            "poline",
            "Address Book Guy",
            "c",
            "V",
            "192.168.1.20:7420",
            // A reply that merely starts with "words" is still an answer.
            "words",
            "Words Worth",
            "wordsmith turtle frog bread wolf paper laptop funnel mango honey wagon",
            "words turtle frog bread wolf paper laptop funnel mango honey",
            "words turtel frog bread wolf paper laptop funnel mango honey wagon",
        ] {
            assert!(!is_whoami_paste_line(answer), "{answer}");
        }
    }

    fn lines(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn pub_hex_prompt_accepts_labelled_whoami_line() {
        // Regression: the pub_hex prompt must not swallow `pub_hex  <hex>`
        // (that hung the TTY and shifted every later answer by one prompt).
        let id = ident(0x0a);
        let hex_pub = hex::encode(id.public_key_bytes());
        let labelled = format!("pub_hex       {}", hex_pub.to_uppercase());
        assert_eq!(
            pick_answer_line(lines(&[&labelled, "poline"]), AnswerKind::PubHex),
            hex_pub
        );
        // A whole whoami block pasted at the pub_hex prompt: address and
        // fingerprint are skipped, the pub_hex line is the answer.
        let addr = format!("address       {}", id.address());
        let fp = format!(
            "fingerprint   {}",
            device_fingerprint_v1(&id.public_key_bytes())
        );
        assert_eq!(
            pick_answer_line(lines(&[&addr, &fp, &labelled]), AnswerKind::PubHex),
            hex_pub
        );
        // ... and so is the `words` line of a newer whoami.
        let words = format!("words         {}", words_text(&id.public_key_bytes()));
        assert_eq!(
            pick_answer_line(lines(&[&addr, &fp, &words, &labelled]), AnswerKind::PubHex),
            hex_pub
        );
        // Bare hex and the invite line both reduce to the pub.
        assert_eq!(
            pick_answer_line(lines(&[&hex_pub]), AnswerKind::PubHex),
            hex_pub
        );
        let inv = format!("invite        {}", invite_for(&id));
        assert_eq!(
            pick_answer_line(lines(&[&inv]), AnswerKind::PubHex),
            hex_pub
        );
        // A broken invite is handed back (add then fails) instead of skipped.
        let other = ident(0x0b);
        let bad = format!(
            "raven:{}:{}",
            id.address(),
            hex::encode(other.public_key_bytes())
        );
        let got = pick_answer_line(lines(&[&bad, "later"]), AnswerKind::PubHex);
        assert_eq!(got, bad);
        assert!(parse_pub_hex(&got).is_err());
        // Garbage / shell text is returned verbatim so the caller rejects it.
        assert_eq!(
            pick_answer_line(lines(&["nope", &hex_pub]), AnswerKind::PubHex),
            "nope"
        );
        let shell = format!("export X={hex_pub}");
        assert_eq!(
            pick_answer_line(lines(&[&shell]), AnswerKind::PubHex),
            shell
        );

        // Free prompts (tag / petname / dial / choice) still skip every
        // leftover whoami line, including the labelled pub_hex one.
        assert_eq!(
            pick_answer_line(lines(&[&labelled, &inv, "poline"]), AnswerKind::Free),
            "poline"
        );
        assert_eq!(pick_answer_line(lines(&[""]), AnswerKind::Free), "");
        // Bounded: never loops forever on a stream of leftovers.
        let many: Vec<String> = std::iter::repeat_n(labelled.clone(), 20).collect();
        assert_eq!(pick_answer_line(many, AnswerKind::Free), "");
    }

    #[test]
    fn add_contact_validates_tag_charset_and_unique_petname() {
        let dir = tempfile::tempdir().unwrap();
        seed_book(dir.path());
        let carol = ident(0x0c);
        let c_hex = hex::encode(carol.public_key_bytes());
        let err = add_contact(
            dir.path(),
            &carol.address(),
            &c_hex,
            "Carol",
            "invite raven:x",
            None,
            "",
        )
        .unwrap_err();
        assert!(err.contains("@tag rejected"), "{err}");
        let err =
            add_contact(dir.path(), &carol.address(), &c_hex, "bob", "", None, "").unwrap_err();
        assert!(err.contains("already used"), "{err}");
        let err = add_contact(
            dir.path(),
            &carol.address(),
            &c_hex,
            "Carol",
            "",
            None,
            "evil\u{1b}[2J:7420",
        )
        .unwrap_err();
        assert!(err.contains("lan_dial"), "{err}");
        assert_eq!(load_contacts(dir.path()).unwrap().len(), 2);
        add_contact(
            dir.path(),
            &carol.address(),
            &c_hex,
            "Carol",
            "@Carol",
            None,
            "",
        )
        .unwrap();
        let book = load_contacts(dir.path()).unwrap();
        assert_eq!(book.len(), 3);
        assert_eq!(book[2].public_tag, "carol");
        // Re-adding the same key under its own petname is an update, not a clash.
        add_contact(dir.path(), &carol.address(), &c_hex, "carol", "", None, "").unwrap();
        assert_eq!(load_contacts(dir.path()).unwrap().len(), 3);
    }

    #[test]
    fn send_picker_never_silently_picks_among_duplicates() {
        let a = ident(0x0a);
        let b = ident(0x0b);
        let row = |id: &Identity, pet: &str, tag: &str| Contact {
            petname: pet.into(),
            public_tag: tag.into(),
            alias: tag.into(),
            address: id.address(),
            pub_hex: hex::encode(id.public_key_bytes()),
            pinned: false,
            lan_dial: String::new(),
            internet_dial: String::new(),
            p2p: String::new(),
            p2p_via: Vec::new(),
            p2p_next: String::new(),
            custodians: Vec::new(),
            hide_ip: false,
            onion: String::new(),
        };
        let book = vec![row(&a, "Sam (Office)", "sam"), row(&b, "Sam (Home)", "sam")];
        assert_eq!(
            pick_send_contact(&book, "@sam"),
            SendPick::Ambiguous(vec![0, 1])
        );
        assert_eq!(
            pick_send_contact(&book, "@SAM"),
            SendPick::Ambiguous(vec![0, 1])
        );
        assert_eq!(pick_send_contact(&book, "2"), SendPick::One(1));
        assert_eq!(pick_send_contact(&book, "sam (home)"), SendPick::One(1));
        assert_eq!(pick_send_contact(&book, "3"), SendPick::NoMatch);
        assert_eq!(pick_send_contact(&book, "0"), SendPick::NoMatch);
        assert_eq!(pick_send_contact(&book, "@nobody"), SendPick::NoMatch);
        let legacy_dupes = vec![row(&a, "Sam", ""), row(&b, "sam", "")];
        assert_eq!(
            pick_send_contact(&legacy_dupes, "Sam"),
            SendPick::Ambiguous(vec![0, 1])
        );
    }

    #[test]
    fn menu_send_uses_secure_pair_init_path() {
        // Menu send is ext::run_send_secure (PairInit / indexed session), never
        // a raven-node `--body-mode unsafe-interim` child: its own validation
        // answers before any process is spawned or dial attempted.
        let dir = tempfile::tempdir().unwrap();
        let me = ident(0x01);
        let peer = ident(0x02);
        let peer_hex = hex::encode(peer.public_key_bytes());
        let err =
            menu_send_secure(dir.path(), &me, "not-a-dial", &peer_hex, "hi", true).unwrap_err();
        assert!(err.contains("lan_dial host:port required"), "{err}");
        let err = menu_send_secure(dir.path(), &me, "127.0.0.1:9", "zz", "hi", true).unwrap_err();
        assert!(err.contains("pub_hex"), "{err}");
        let mut blocks = BlockList::load_checked(dir.path()).unwrap();
        blocks.block(&peer_hex);
        blocks.save(dir.path()).unwrap();
        let err =
            menu_send_secure(dir.path(), &me, "127.0.0.1:9", &peer_hex, "hi", true).unwrap_err();
        assert!(err.contains("block list"), "{err}");
    }

    /// E1: with this profile's raven-node running and receiving, the empty
    /// inbox no longer sends the user to `ash listen` and menu 5.
    #[test]
    fn an_empty_inbox_says_a_running_node_receives() {
        let dir = Path::new("/tmp/raven-profile");
        let receiving = inbox_empty_text(dir, true);
        assert!(
            receiving.starts_with("No messages yet in /tmp/raven-profile."),
            "{receiving}"
        );
        assert!(
            receiving.contains("This computer is receiving"),
            "{receiving}"
        );
        assert!(!receiving.contains("ash listen"), "{receiving}");
        assert!(!receiving.contains("menu 5"), "{receiving}");
        let not = inbox_empty_text(dir, false);
        assert!(not.contains("keep `ash listen` running"), "{not}");
        assert!(not.contains("this computer is not receiving"), "{not}");
    }

    #[test]
    fn inbox_rows_say_how_a_message_came_when_raven_node_knows() {
        use raven_core::arrivals::ArrivedVia;
        let plain = |s: String| {
            let mut out = String::new();
            let mut chars = s.chars();
            while let Some(c) = chars.next() {
                if c == '\u{1b}' {
                    for d in chars.by_ref() {
                        if d.is_ascii_alphabetic() {
                            break;
                        }
                    }
                } else {
                    out.push(c);
                }
            }
            out
        };
        assert_eq!(plain(arrival_suffix(Some(ArrivedVia::Tor))), "  via Tor");
        assert_eq!(
            plain(arrival_suffix(Some(ArrivedVia::Keeper))),
            "  from a keeper"
        );
        assert_eq!(plain(arrival_suffix(Some(ArrivedVia::Lan))), "  via LAN");
        assert_eq!(arrival_suffix(None), "");
    }

    #[test]
    fn inbox_rows_are_attributed_and_single_line() {
        let a = ident(0x0a);
        let stranger = ident(0x0f);
        let book = vec![Contact {
            petname: "Alice".into(),
            public_tag: String::new(),
            alias: String::new(),
            address: a.address(),
            pub_hex: hex::encode(a.public_key_bytes()),
            pinned: true,
            lan_dial: String::new(),
            internet_dial: String::new(),
            p2p: String::new(),
            p2p_via: Vec::new(),
            p2p_next: String::new(),
            custodians: Vec::new(),
            hide_ip: false,
            onion: String::new(),
        }];
        let mid = [0xabu8; 16];
        let forged =
            b"ok\r  \xe2\x86\x92 1a2b3c4d I agree to pay\n  \xe2\x86\x90 99999999 Alice: hi";
        let line = format_inbox_row(
            &book,
            &a.public_key_bytes(),
            &mid,
            forged,
            "5 min ago",
            None,
        );
        assert!(!line.contains('\r') && !line.contains('\n'), "{line:?}");
        assert!(line.contains("Alice"));
        assert!(line.contains("pinned"));
        assert!(line.contains(&device_fingerprint_v1(&a.public_key_bytes())));
        let line = format_inbox_row(
            &book,
            &stranger.public_key_bytes(),
            &mid,
            b"This is Alice: pay",
            "",
            None,
        );
        assert!(line.contains("unknown device"), "{line}");
        assert!(line.contains(&device_fingerprint_v1(&stranger.public_key_bytes())));
        assert!(!line.contains("Alice ["), "{line}");
    }

    fn inbox_row(
        sender: u8,
        mid: u8,
        body: &[u8],
        received_at_ms: u64,
    ) -> raven_core::indexed_session_store::EndpointInboxRow {
        raven_core::indexed_session_store::EndpointInboxRow {
            session_id: [received_at_ms as u8; 32],
            object_digest: [received_at_ms as u8; 32],
            message_id: [mid; 16],
            sender_device: [sender; 32],
            created_at_ms: 1,
            received_at_ms,
            position: raven_core::indexed_session_store::InboxPosition::received(
                received_at_ms,
                Some([mid; 16]),
            ),
            plaintext: body.to_vec(),
        }
    }

    /// Receiver dedup (P5.5): copies with the same sender, id and body fold
    /// into the earliest (body and note); a copy with another body stays (an
    /// integrity conflict is visible); a later copy whose first one is gone
    /// shows the note alone. With dedup off nothing changes.
    #[test]
    fn inbox_copies_fold_and_a_copy_seen_before_is_received_again() {
        let rows = || {
            vec![
                inbox_row(1, 0xA1, b"hello", 10),
                inbox_row(2, 0xA1, b"hello", 11),
                inbox_row(1, 0xA1, b"hello", 12),
                inbox_row(1, 0xA1, b"other text", 13),
                inbox_row(1, 0xA2, b"again", 14),
                inbox_row(1, 0xA2, b"again", 15),
                inbox_row(1, 0xA3, b"fresh", 16),
            ]
        };
        // 0xA2 from 1 was taken before its first listed copy.
        let seen_before = |row: &raven_core::indexed_session_store::EndpointInboxRow| {
            row.message_id == [0xA2; 16] && row.sender_device == [1; 32]
        };
        let shown: Vec<(u64, InboxCopy)> = collapse_inbox_copies(rows(), true, seen_before)
            .into_iter()
            .map(|(row, copy)| (row.received_at_ms, copy))
            .collect();
        assert_eq!(
            shown,
            vec![
                (10, InboxCopy::WithCopies),
                (11, InboxCopy::Only),
                (13, InboxCopy::Only),
                (14, InboxCopy::Again),
                (16, InboxCopy::Only),
            ]
        );
        let off: Vec<(u64, InboxCopy)> = collapse_inbox_copies(rows(), false, |_| true)
            .into_iter()
            .map(|(row, copy)| (row.received_at_ms, copy))
            .collect();
        assert_eq!(
            off,
            (10..=16)
                .map(|at| (at, InboxCopy::Only))
                .collect::<Vec<_>>()
        );
    }

    /// A received message as the chat history keeps it.
    fn kept_row(
        sender: u8,
        mid: u8,
        body: &str,
        stored_at_ms: Option<u64>,
        created_at_ms: u64,
    ) -> raven_core::ChatHistoryEntry {
        raven_core::ChatHistoryEntry {
            message_id_hex: hex::encode([mid; 16]),
            direction: "in".into(),
            peer_petname: "Alice".into(),
            peer_tag: String::new(),
            peer_pub_hex: hex::encode([sender; 32]),
            created_at_ms,
            delivery: "received".into(),
            preview: body.into(),
            body: body.into(),
            stored_at_ms,
        }
    }

    /// E2 round 7: a session that ended took its inbox rows with it, and
    /// the inbox said "No messages yet" though the chat history kept every
    /// message. The history's received messages are listed too: once each,
    /// in the order they arrived; a copy seen before whose first copy the
    /// history keeps shows its body; a row that does not decode is counted,
    /// never shown.
    #[test]
    fn the_inbox_lists_what_only_the_history_keeps_once_and_in_order() {
        let rows = vec![
            (inbox_row(1, 0xB2, b"live", 20), InboxCopy::Only),
            (inbox_row(1, 0xB3, b"again", 40), InboxCopy::Again),
            (
                inbox_row(1, 0xB5, b"again, first gone", 50),
                InboxCopy::Again,
            ),
        ];
        let kept = vec![
            kept_row(1, 0xB1, "ended", Some(10), 5),
            // Also in its live session: listed once, from there.
            kept_row(1, 0xB2, "live", Some(19), 19),
            // The first copy of the one received again.
            kept_row(1, 0xB3, "again", Some(30), 30),
            // A plain profile's row: by its sender's stamp.
            kept_row(2, 0xB4, "plain profile", None, 25),
            raven_core::ChatHistoryEntry {
                peer_pub_hex: "not hex".into(),
                ..kept_row(3, 0xB6, "unreadable", Some(1), 1)
            },
        ];
        let (lines, unreadable) = inbox_lines(rows, kept);
        let shown: Vec<(u64, String, InboxCopy)> = lines
            .into_iter()
            .map(|line| {
                (
                    line.received_at_ms,
                    String::from_utf8(line.body).unwrap(),
                    line.copy,
                )
            })
            .collect();
        assert_eq!(
            shown,
            vec![
                (10, "ended".to_string(), InboxCopy::Only),
                (20, "live".to_string(), InboxCopy::Only),
                (25, "plain profile".to_string(), InboxCopy::Only),
                (40, "again".to_string(), InboxCopy::WithCopies),
                (50, "again, first gone".to_string(), InboxCopy::Again),
            ]
        );
        assert_eq!(unreadable, 1);
        assert_eq!(inbox_lines(Vec::new(), Vec::new()), (Vec::new(), 0));
    }

    /// What cannot be read is said, never "No messages yet" (E2 round 7).
    #[test]
    fn an_inbox_that_cannot_be_read_says_why() {
        let dir = Path::new("/tmp/raven-profile");
        assert_eq!(
            inbox_unreadable_text(dir, Some("the keystore said no"), 2),
            "Raven can't read the chat history in /tmp/raven-profile now, so the messages it \
             keeps are not shown. They are not deleted. Why: the keystore said no\n2 received \
             message(s) in /tmp/raven-profile could not be read, so they are not shown. They \
             are not deleted."
        );
        assert_eq!(
            inbox_unreadable_text(dir, None, 1),
            "1 received message(s) in /tmp/raven-profile could not be read, so they are not \
             shown. They are not deleted."
        );
    }

    /// A row shown once is exactly today's line; a folded row adds the note
    /// after its body; a copy seen before shows the note, never its body.
    #[test]
    fn inbox_row_shows_received_again_note() {
        let a = ident(0x0a);
        let mid = [0xabu8; 16];
        let plain = format_inbox_row(
            &[],
            &a.public_key_bytes(),
            &mid,
            b"hello",
            "1 min ago",
            None,
        );
        let only = format_inbox_row_copy(
            &[],
            &a.public_key_bytes(),
            &mid,
            b"hello",
            "1 min ago",
            None,
            InboxCopy::Only,
        );
        assert_eq!(plain, only);
        assert!(!only.contains(RECEIVED_AGAIN_NOTE), "{only}");
        let folded = format_inbox_row_copy(
            &[],
            &a.public_key_bytes(),
            &mid,
            b"hello",
            "1 min ago",
            None,
            InboxCopy::WithCopies,
        );
        assert!(
            folded.contains("hello") && folded.contains(RECEIVED_AGAIN_NOTE),
            "{folded}"
        );
        let again = format_inbox_row_copy(
            &[],
            &a.public_key_bytes(),
            &mid,
            b"hello",
            "1 min ago",
            None,
            InboxCopy::Again,
        );
        assert!(!again.contains("hello"), "{again}");
        assert!(again.contains(RECEIVED_AGAIN_NOTE), "{again}");
        assert!(again.contains(&hex::encode(&mid[..4])), "{again}");
        assert!(!again.contains('\n'), "{again:?}");
    }

