    #[test]
    fn listener_ready_needs_lan_direct_in_ipc_status() {
        // IPC answering is not enough: the IPC task can be up (or about to
        // fail on the instance lock) before the LAN port is bound.
        assert!(!status_reports_lan_listener(&status_with_caps(&["ipc"])));
        assert!(status_reports_lan_listener(&status_with_caps(&[
            "ipc",
            "lan_direct",
            "store"
        ])));
        assert!(!status_reports_lan_listener(&Ok(IpcResponse::Pong {
            v: IPC_VERSION
        })));
        assert!(!status_reports_lan_listener(&Err("dial failed".into())));
    }

    #[cfg(unix)]
    fn spawn_sh(script: &str) -> std::process::Child {
        Command::new("sh")
            .args(["-c", script])
            .stdin(std::process::Stdio::null())
            .spawn()
            .unwrap()
    }

    #[cfg(unix)]
    #[test]
    fn listen_wait_reports_an_early_exit_never_ready() {
        // A service that dies on startup is an exit (with its status), not LISTENING.
        let mut child = spawn_sh("exit 3");
        let got = wait_for_listener(
            &mut child,
            Duration::from_secs(60),
            Duration::from_millis(2),
            Duration::ZERO,
            || false,
        );
        match got {
            ListenWait::Exited(st) => assert_eq!(st.code(), Some(3)),
            other => panic!("{other:?}"),
        }
    }

    #[cfg(unix)]
    #[test]
    fn listen_wait_is_ready_while_the_child_lives_and_times_out_otherwise() {
        let mut child = spawn_sh("sleep 60");
        let got = wait_for_listener(
            &mut child,
            Duration::from_secs(60),
            Duration::from_millis(2),
            Duration::ZERO,
            || true,
        );
        assert!(matches!(got, ListenWait::Ready), "{got:?}");
        // The listener never reports up: a bounded wait ends in TimedOut
        // (the caller warns instead of announcing LISTENING).
        let got = wait_for_listener(
            &mut child,
            Duration::from_millis(30),
            Duration::from_millis(2),
            Duration::ZERO,
            || false,
        );
        assert!(matches!(got, ListenWait::TimedOut), "{got:?}");
        child.kill().unwrap();
        child.wait().unwrap();
    }

    #[test]
    fn listen_address_comes_from_flag_then_env_then_default() {
        let addr = |s: &str| ListenOn::Addr(s.parse::<std::net::SocketAddr>().unwrap());
        let default = addr("0.0.0.0:7420");
        // The flag wins over the variable, the variable over the default.
        assert_eq!(
            resolve_listen_addr(Some("0.0.0.0:7430"), Some("0.0.0.0:7424"), default),
            Ok((addr("0.0.0.0:7430"), None))
        );
        assert_eq!(
            resolve_listen_addr(None, Some("0.0.0.0:7424"), default),
            Ok((addr("0.0.0.0:7424"), None))
        );
        assert_eq!(
            resolve_listen_addr(None, None, default),
            Ok((addr("0.0.0.0:7420"), None))
        );
        // Port 0 in the variable is the outbound-only setting ash suggests for a
        // send: `ash listen` keeps working on the default port and says why.
        let (got, note) = resolve_listen_addr(None, Some("127.0.0.1:0"), default).unwrap();
        assert_eq!(got, addr("0.0.0.0:7420"));
        let note = note.expect("a note");
        for word in [
            "RAVEN_SERVICE_LAN_LISTEN=127.0.0.1:0",
            "outbound-only",
            "--listen",
        ] {
            assert!(note.contains(word), "{word:?} missing from: {note}");
        }
        let (got, note) = resolve_listen_addr(None, Some("not-an-address"), default).unwrap();
        assert_eq!(got, addr("0.0.0.0:7420"));
        assert!(note.is_some_and(|n| n.contains("not an IP:PORT")));
        // On the flag, a port friends cannot dial is refused.
        for bad in ["0.0.0.0:0", "nope", ""] {
            let err = resolve_listen_addr(Some(bad), Some("0.0.0.0:7424"), default).unwrap_err();
            assert!(err.contains("--listen needs a fixed port"), "{err}");
        }
    }

    /// B-5: `ash listen --listen [fe80::1%en0]:7424` takes the zone by the
    /// interface's name (held by its index, which raven-node binds) as by
    /// number; an unknown interface is refused like any bad address.
    #[test]
    fn listen_takes_an_ipv6_zone_by_name() {
        let fixed = ListenOn::Addr("0.0.0.0:7420".parse().unwrap());
        let scoped = |scope: u32| {
            ListenOn::Addr(std::net::SocketAddr::V6(std::net::SocketAddrV6::new(
                "fe80::1".parse().unwrap(),
                7424,
                0,
                scope,
            )))
        };
        assert_eq!(
            resolve_listen_addr(Some("[fe80::1%3]:7424"), None, fixed),
            Ok((scoped(3), None))
        );
        let lo = if cfg!(windows) {
            "loopback_0"
        } else if cfg!(target_os = "linux") {
            "lo"
        } else {
            "lo0"
        };
        if let Some(index) = raven_core::netifs::interface_index(lo) {
            let (got, note) =
                resolve_listen_addr(Some(&format!("[fe80::1%{lo}]:7424")), None, fixed).unwrap();
            assert_eq!((got, note), (scoped(index), None));
            assert_eq!(got.to_string(), format!("[fe80::1%{index}]:7424"));
        }
        let err = resolve_listen_addr(Some("[fe80::1%no-such-if0]:7424"), None, fixed).unwrap_err();
        assert!(err.contains("--listen needs a fixed port"), "{err}");
    }

    /// Phase 3 P3.6: `auto` and `auto:PORT` on the flag and in the variable,
    /// and as the default while its gate is live; raven-node takes it as
    /// given, and the texts keep it.
    #[test]
    fn listen_takes_auto_and_auto_port() {
        let auto = ListenOn::Auto { port: 7420 };
        let auto_7424 = ListenOn::Auto { port: 7424 };
        let fixed = ListenOn::Addr("0.0.0.0:7420".parse().unwrap());
        assert_eq!(
            resolve_listen_addr(Some("auto"), Some("0.0.0.0:7424"), fixed),
            Ok((auto, None))
        );
        assert_eq!(
            resolve_listen_addr(Some(" AUTO:7424 "), None, fixed),
            Ok((auto_7424, None))
        );
        assert_eq!(
            resolve_listen_addr(None, Some("auto:7424"), fixed),
            Ok((auto_7424, None))
        );
        assert_eq!(resolve_listen_addr(None, None, auto), Ok((auto, None)));
        for bad in ["auto:0", "auto:", "auto:x", "auto:65536"] {
            let err = resolve_listen_addr(Some(bad), None, fixed).unwrap_err();
            assert!(err.contains("--listen needs a fixed port"), "{err}");
            assert!(err.contains("or auto"), "{err}");
        }
        let (got, note) = resolve_listen_addr(None, Some("auto:0"), auto).unwrap();
        assert_eq!(got, auto);
        assert!(note.is_some_and(|n| n.contains("not an IP:PORT or auto")));
        // As raven-node's --lan-listen takes it; its IPv4 socket for the checks.
        assert_eq!(auto.to_string(), "auto");
        assert_eq!(auto_7424.to_string(), "auto:7424");
        assert_eq!(fixed.to_string(), "0.0.0.0:7420");
        assert_eq!(auto_7424.addr().to_string(), "0.0.0.0:7424");
        // A profile without a picked port (Phase 6b P6.36): the default.
        let fresh = tempfile::tempdir().unwrap();
        assert_eq!(
            ListenOn::service_default(fresh.path()),
            ListenOn::parse(&ext::default_service_lan_listen()).unwrap()
        );
        // A busy port offers `auto` on the next free one.
        let msg = port_taken_message(auto, None, None);
        assert!(msg.contains("port 7420 (auto) is already taken"), "{msg}");
        assert!(msg.contains("ash listen --listen auto:7424"), "{msg}");
        // The export hint keeps `auto`.
        let hint = listen_export_hint(auto_7424, None).unwrap();
        assert!(
            hint.contains("RAVEN_SERVICE_LAN_LISTEN=auto:7424"),
            "{hint}"
        );
        assert_eq!(listen_export_hint(auto_7424, Some("auto:7424")), None);
        assert_eq!(listen_export_hint(auto, None), None);
        // A send's hint without a service: `auto` is every network, its port.
        assert_eq!(
            unresolved_hint_listen(None, Some("auto:7424")),
            Ok("0.0.0.0:7424".parse().unwrap())
        );
    }

    /// Phase 3 P3.6: the preflight checks both families for `auto` while its
    /// gate is live (no IPv6 on this computer is no taken port: raven-node
    /// then listens on IPv4 alone), `0.0.0.0:PORT` alone while it is closed,
    /// and a fixed address as before.
    #[test]
    fn listen_preflight_checks_both_families_for_auto() {
        let check = |listen: ListenOn, live: bool, taken: &[&str], no_v6: bool| {
            let asked = std::cell::RefCell::new(Vec::<String>::new());
            let free = listen_ports_free(listen, live, |at| {
                asked.borrow_mut().push(at.to_string());
                if taken.contains(&at.to_string().as_str()) {
                    Err(io::Error::from(io::ErrorKind::AddrInUse))
                } else if no_v6 && at.is_ipv6() {
                    Err(io::Error::from(io::ErrorKind::AddrNotAvailable))
                } else {
                    Ok(())
                }
            });
            (free, asked.into_inner())
        };
        let both = vec!["0.0.0.0:7431".to_string(), "[::]:7431".to_string()];
        let v4 = vec!["0.0.0.0:7431".to_string()];
        let auto = ListenOn::Auto { port: 7431 };
        assert_eq!(check(auto, true, &[], false), (true, both.clone()));
        assert_eq!(check(auto, true, &["[::]:7431"], false), (false, both));
        assert_eq!(
            check(auto, true, &["0.0.0.0:7431"], false),
            (false, v4.clone())
        );
        assert!(check(auto, true, &[], true).0, "IPv6 unavailable");
        assert_eq!(
            check(auto, false, &["[::]:7431"], false),
            (true, v4.clone())
        );
        let fixed = ListenOn::Addr("0.0.0.0:7431".parse().unwrap());
        assert_eq!(check(fixed, true, &[], false), (true, v4));
        let fixed6 = ListenOn::Addr("[::]:7431".parse().unwrap());
        assert!(
            !check(fixed6, true, &[], true).0,
            "a fixed address as before"
        );
        // What this profile's service says is read on `auto`'s IPv4 socket:
        // never a loopback address.
        let local = ProfileService {
            receiving: true,
            lan_listen: Some("127.0.0.1:60798".into()),
            pid: Some(4242),
        };
        assert_eq!(
            listen_preflight(true, Some(&local), auto.addr()),
            ListenPreflight::ServiceNotReceiving {
                pid: Some(4242),
                local_only: Some("127.0.0.1:60798".into())
            }
        );
    }

    /// Phase 3 P3.6: `raven listen` refuses while `raven lan off` holds.
    #[test]
    fn listen_refuses_with_lan_off() {
        assert_eq!(listen_lan_off_refusal(false), None);
        let refusal = listen_lan_off_refusal(true).expect("a refusal");
        assert!(
            refusal.starts_with("LAN_OFF: LAN is off on this computer"),
            "{refusal}"
        );
        assert!(
            refusal.ends_with("Turn it back on with: raven lan on"),
            "{refusal}"
        );
    }

    #[test]
    fn listen_preflight_tells_a_second_profile_apart() {
        use ListenPreflight as P;
        let svc = |receiving: bool, pid: Option<u32>| ProfileService {
            receiving,
            lan_listen: receiving.then(|| "0.0.0.0:7424".to_string()),
            pid,
        };
        let listen: std::net::SocketAddr = "0.0.0.0:7420".parse().unwrap();
        assert_eq!(listen_preflight(true, None, listen), P::Start);
        assert_eq!(
            listen_preflight(false, None, listen),
            P::PortTaken {
                our_service: false,
                our_pid: None
            }
        );
        for port_free in [true, false] {
            assert_eq!(
                listen_preflight(port_free, Some(&svc(true, Some(7))), listen),
                P::AlreadyReceiving {
                    on: Some("0.0.0.0:7424".into())
                }
            );
        }
        assert_eq!(
            listen_preflight(true, Some(&svc(false, Some(7))), listen),
            P::ServiceNotReceiving {
                pid: Some(7),
                local_only: None
            }
        );
        assert_eq!(
            listen_preflight(true, Some(&svc(false, None)), listen),
            P::ServiceNotReceiving {
                pid: None,
                local_only: None
            }
        );
        // The old wrong case: the port is busy (a second profile's service holds
        // it) and this profile's service answers but receives nothing. That used
        // to print "It already receives".
        assert_eq!(
            listen_preflight(false, Some(&svc(false, Some(4242))), listen),
            P::PortTaken {
                our_service: true,
                our_pid: Some(4242)
            }
        );
        assert_eq!(
            listen_preflight(false, Some(&svc(false, None)), listen),
            P::PortTaken {
                our_service: true,
                our_pid: None
            }
        );
        // An older raven-node does not say where it receives.
        let old = ProfileService {
            receiving: true,
            lan_listen: None,
            pid: None,
        };
        assert_eq!(
            listen_preflight(false, Some(&old), listen),
            P::AlreadyReceiving { on: None }
        );
    }

    /// A service on a loopback address (the outbound-only setting) reports its
    /// listener up, but no other computer reaches it: for an `ash listen` on an
    /// address they do reach it does not already receive, on any port and
    /// whether or not that port is free (it has to stop first either way).
    #[test]
    fn listen_preflight_does_not_count_a_loopback_service_as_receiving() {
        use ListenPreflight as P;
        let a = |s: &str| s.parse::<std::net::SocketAddr>().unwrap();
        let local = ProfileService {
            receiving: true,
            lan_listen: Some("127.0.0.1:60798".into()),
            pid: Some(4242),
        };
        for want in [
            "0.0.0.0:7431",
            "0.0.0.0:60798",
            "192.168.1.9:7431",
            "[::]:7431",
        ] {
            for port_free in [true, false] {
                assert_eq!(
                    listen_preflight(port_free, Some(&local), a(want)),
                    P::ServiceNotReceiving {
                        pid: Some(4242),
                        local_only: Some("127.0.0.1:60798".into())
                    },
                    "{want} free={port_free}"
                );
            }
        }
        // Asked for this computer only: it does receive there.
        for want in ["127.0.0.1:7431", "127.0.0.1:60798"] {
            assert_eq!(
                listen_preflight(false, Some(&local), a(want)),
                P::AlreadyReceiving {
                    on: Some("127.0.0.1:60798".into())
                },
                "{want}"
            );
        }
        // The refusal names where it does listen, and how to stop that one.
        let dir = Path::new("/tmp/profile-b");
        let msg = service_not_receiving_message(
            dir,
            a("0.0.0.0:7431"),
            Some(4242),
            Some("127.0.0.1:60798"),
            None,
        );
        for word in [
            "is NOT receiving on 0.0.0.0:7431",
            "it listens only on 127.0.0.1:60798, which other computers cannot reach",
            &ext::profile_stop_advice(dir, Some(4242)),
            "then run `ash listen` again",
        ] {
            assert!(msg.contains(word), "{word:?} missing from: {msg}");
        }
    }

    /// The installers' default is a login service on 127.0.0.1:7420, and
    /// launchd's KeepAlive (the task's restarts) starts a killed one again:
    /// a kill and `ash listen` would go round for ever. With a login service
    /// every text leads with reinstalling it, and stops it with its own
    /// command, never `kill <pid>` (D-interfaces-texts-3).
    #[test]
    fn a_login_service_on_this_computer_only_is_never_told_to_be_killed() {
        use tui::Managed;
        let a = |s: &str| s.parse::<std::net::SocketAddr>().unwrap();
        let dir = Path::new("/tmp/profile-a");
        let launchd = service_steps(Managed::LaunchAgent);
        assert_eq!(
            launchd.stop,
            "launchctl bootout gui/$(id -u)/com.raven.raven-node"
        );
        assert_eq!(
            launchd.reinstall,
            "RAVEN_LAN_LISTEN=0.0.0.0:7420 bash node/scripts/install/macos_launchd.sh"
        );
        let local = |service| NodeReach::ReceiveLocalOnly {
            listen: "127.0.0.1:7420".into(),
            service,
        };
        for (service, stop, reinstall) in [
            (
                Managed::LaunchAgent,
                "launchctl bootout gui/$(id -u)/com.raven.raven-node",
                "RAVEN_LAN_LISTEN=0.0.0.0:7420 bash node/scripts/install/macos_launchd.sh",
            ),
            (
                Managed::SystemdUser,
                "systemctl --user stop raven-node",
                "RAVEN_LAN_LISTEN=0.0.0.0:7420 bash node/scripts/install/linux_systemd_user.sh",
            ),
            (
                Managed::ScheduledTask,
                "Stop-ScheduledTask -TaskName RavenNodeBridge",
                ".\\node\\scripts\\install\\windows_service.ps1 -LanListen 0.0.0.0:7420",
            ),
        ] {
            let steps = service_steps(service);
            assert_eq!((steps.stop, steps.reinstall.as_str()), (stop, reinstall));
            let row = node_reach_row(&local(Some(service)));
            let step = doctor_next_step(IdentityState::Ready, Some(2), &local(Some(service)));
            let refused = service_not_receiving_message(
                dir,
                a("0.0.0.0:7420"),
                Some(4242),
                Some("127.0.0.1:7420"),
                Some(service),
            );
            let waiting =
                port_taken_message(a("0.0.0.0:7420"), Some((dir, Some(4242))), Some(service));
            // The port's other program may be killed; this profile's
            // login service never is.
            let ours = waiting
                .lines()
                .find(|l| l.starts_with("This profile's raven-node is also waiting"))
                .unwrap_or_else(|| panic!("{waiting}"))
                .to_owned();
            for text in [&row, &step, &refused, &ours] {
                assert!(text.contains(stop), "{stop:?} missing from: {text}");
                for kill in ["kill 4242", "/PID", "pkill", "4242"] {
                    assert!(!text.contains(kill), "{kill:?} in: {text}");
                }
            }
            // Reinstalling comes before the one-off `ash listen`.
            for text in [&row, &step] {
                let at = |word: &str| {
                    text.find(word)
                        .unwrap_or_else(|| panic!("{word:?} in {text}"))
                };
                assert!(at(reinstall) < at("ash listen"), "{text}");
                assert!(text.contains(steps.start), "{text}");
            }
            assert!(row.starts_with("ONLY THIS COMPUTER \u{2014} the login service runs raven-node on 127.0.0.1:7420"), "{row}");
            assert!(step.starts_with("friends cannot reach you: the login service runs raven-node on this computer only (127.0.0.1:7420)"), "{step}");
            assert!(
                refused.contains("It is the login service: a kill may only get it started again"),
                "{refused}"
            );
            assert!(refused.contains(reinstall), "{refused}");
            // The verdict and the doctor's key line stay as they were.
            assert_eq!(
                node_reach_verdict(&local(Some(service))),
                node_reach_verdict(&local(None))
            );
            assert_eq!(
                doctor_receiving_key(&local(Some(service))),
                "local_only (127.0.0.1:7420)"
            );
        }
        // No login service: a process ash or a send started, stopped by its pid.
        let refused = service_not_receiving_message(
            dir,
            a("0.0.0.0:7420"),
            Some(4242),
            Some("127.0.0.1:7420"),
            None,
        );
        assert!(
            refused.contains(&ext::profile_stop_advice(dir, Some(4242))),
            "{refused}"
        );
        assert!(
            node_reach_row(&local(None)).contains("Run `ash listen` to listen on your networks")
        );
        // The service is read only for a listener on this computer only.
        let read = std::cell::Cell::new(0);
        let service = || {
            read.set(read.get() + 1);
            Some(Managed::LaunchAgent)
        };
        assert_eq!(
            local(None).run_by(service),
            local(Some(Managed::LaunchAgent))
        );
        for reach in [
            NodeReach::SendAndReceive,
            NodeReach::NotRunning,
            addr_not_here(),
        ] {
            assert_eq!(reach.clone().run_by(service), reach);
        }
        assert_eq!(read.get(), 1);
    }

    /// The already-receiving screen names the port the service reports; an
    /// older raven-node reports none, and then no port is named at all (the
    /// one asked for would send friends to a dead port).
    #[test]
    fn already_receiving_never_names_the_asked_port_as_the_services() {
        let a = |s: &str| s.parse::<std::net::SocketAddr>().unwrap();
        let stop = "kill 4242";
        let lan = [lan_addr("en0", "192.168.1.9")];
        let known = already_receiving_text(Some(a("0.0.0.0:7420")), a("0.0.0.0:7424"), &lan, stop);
        assert!(
            known.headline.ends_with("receiving on port 7420"),
            "{known:?}"
        );
        assert_eq!(known.tell_friend, Some(lan_tip(7420, &lan)));
        let Some(FriendTip::Addresses { heading, rows }) = &known.tell_friend else {
            panic!("{known:?}");
        };
        assert!(heading.contains("port 7420"), "{heading}");
        assert_eq!(rows, &["  192.168.1.9:7420    (Wi-Fi or cable: en0)"]);
        assert!(
            known.notes.iter().any(
                |n| n.contains("To receive on 0.0.0.0:7424 instead, stop it first (kill 4242)")
            ),
            "{known:?}"
        );
        // Same port: nothing to stop.
        let same = already_receiving_text(Some(a("0.0.0.0:7424")), a("0.0.0.0:7424"), &lan, stop);
        assert!(!same.notes.iter().any(|n| n.contains(stop)), "{same:?}");
        assert_eq!(same.tell_friend, Some(lan_tip(7424, &lan)));
        // An older raven-node: the asked port is never presented as its port.
        let old = already_receiving_text(None, a("0.0.0.0:7424"), &lan, stop);
        assert_eq!(old.tell_friend, None, "{old:?}");
        assert!(!old.headline.contains("7424"), "{old:?}");
        assert!(
            old.headline.contains("does not say on which port"),
            "{old:?}"
        );
        assert!(
            old.notes.iter().any(|n| n.contains(
                "To receive on 0.0.0.0:7424 with this version, stop it first (kill 4242)"
            )),
            "{old:?}"
        );
    }

    #[test]
    fn busy_port_advice_never_kills_every_raven_node() {
        let listen: std::net::SocketAddr = "0.0.0.0:7420".parse().unwrap();
        let dir = Path::new("/tmp/profile-b");
        let by_pid = if cfg!(windows) {
            "taskkill /F /PID 4242"
        } else {
            "kill 4242"
        };
        let taken = [
            port_taken_message(listen, None, None),
            port_taken_message(listen, Some((dir, Some(4242))), None),
            port_taken_message(listen, Some((dir, None)), None),
        ];
        let not_receiving = [
            service_not_receiving_message(dir, listen, Some(4242), None, None),
            service_not_receiving_message(dir, listen, None, None, None),
        ];
        for msg in taken.iter().chain(&not_receiving) {
            assert!(!msg.contains("pkill -f raven-node"), "{msg}");
            assert!(!msg.contains("pkill -f 'raven-node service'"), "{msg}");
            assert!(msg.contains("0.0.0.0:7420"), "{msg}");
        }
        for msg in &taken {
            for word in [
                "port 7420 (0.0.0.0:7420) is already taken by another program",
                "<PID>",
                "if it is RAVEN for another profile, leave it running",
                "ash listen --listen 0.0.0.0:7424",
            ] {
                assert!(msg.contains(word), "{word:?} missing from: {msg}");
            }
        }
        assert!(
            !taken[0].contains("This profile's raven-node"),
            "{}",
            taken[0]
        );
        assert!(taken[1].contains(by_pid), "{}", taken[1]);
        assert!(not_receiving[0].contains(by_pid), "{}", not_receiving[0]);
        // An older raven-node does not report its id: this profile's service only.
        let by_profile = ext::profile_stop_advice(dir, None);
        assert!(taken[2].contains(&by_profile), "{}", taken[2]);
        assert!(
            not_receiving[1].contains(&by_profile),
            "{}",
            not_receiving[1]
        );
    }

    #[test]
    fn the_listen_screen_names_the_port_it_really_uses() {
        let a = |s: &str| s.parse::<std::net::SocketAddr>().unwrap();
        let lan = [lan_addr("en0", "192.168.1.9")];
        let one = |row: &str| FriendTip::Addresses {
            heading: "Tell your friend to send to:".into(),
            rows: vec![row.into()],
        };
        assert_eq!(friend_tip(a("0.0.0.0:7424"), &lan), lan_tip(7424, &lan));
        // Only the addresses the listener takes: 0.0.0.0 none of IPv6.
        let both = [lan_addr("en0", "192.168.1.9"), lan_addr("en0", "fd00::7")];
        assert_eq!(friend_tip(a("0.0.0.0:7424"), &both), lan_tip(7424, &lan));
        assert_eq!(
            friend_tip(a("[::]:7424"), &both),
            lan_tip(7424, if cfg!(windows) { &both[1..] } else { &both })
        );
        assert_eq!(
            friend_tip(a("0.0.0.0:7424"), &both[1..]),
            FriendTip::NoNetwork
        );
        assert_eq!(
            friend_tip(a("127.0.0.1:7424"), &lan),
            one("   127.0.0.1:7424 (this computer only)")
        );
        assert_eq!(
            friend_tip(a("192.168.1.9:7430"), &[lan_addr("en1", "10.0.0.2")]),
            one("   192.168.1.9:7430")
        );
        // Bound to one address, on no network: still that address.
        assert_eq!(
            friend_tip(a("127.0.0.1:7424"), &[]),
            one("   127.0.0.1:7424 (this computer only)")
        );
        assert_eq!(local_dial_addr(a("0.0.0.0:7424")), a("127.0.0.1:7424"));
        assert_eq!(local_dial_addr(a("[::]:7424")), a("[::1]:7424"));
        assert_eq!(
            local_dial_addr(a("192.168.1.9:7424")),
            a("192.168.1.9:7424")
        );
        // The port is not saved: a send that starts the service uses the variable.
        assert_eq!(listen_export_hint(a("0.0.0.0:7420"), None), None);
        assert_eq!(
            listen_export_hint(a("0.0.0.0:7424"), Some("0.0.0.0:7424")),
            None
        );
        let hint = listen_export_hint(a("0.0.0.0:7424"), None).unwrap();
        assert!(
            hint.contains("RAVEN_SERVICE_LAN_LISTEN=0.0.0.0:7424"),
            "{hint}"
        );
        assert!(listen_export_hint(a("0.0.0.0:7424"), Some("127.0.0.1:0")).is_some());
    }

    fn signed_claim(id: &Identity, alias: &str, sequence: u64) -> AliasRecord {
        AliasRecord {
            alias: alias.into(),
            identity_address: id.address(),
            sequence,
            expires_at: now_ms() + 60_000,
            signature: [0u8; 64],
            ed25519_pub: id.public_key_bytes(),
        }
        .sign(id)
        .unwrap()
    }

    #[test]
    fn alias_publish_never_regresses_the_stored_sequence() {
        let dir = tempfile::tempdir().unwrap();
        let id = ident(0x0a);
        let addr = id.address();
        save_alias_claim(dir.path(), &signed_claim(&id, "alice", 5)).unwrap();
        // A refresh published with the old default (1), or a replay (5), is
        // refused: peers holding seq 5 would reject it as ALIAS_STALE_SEQUENCE.
        for seq in [1, 4, 5] {
            let err = save_alias_claim(dir.path(), &signed_claim(&id, "alice", seq)).unwrap_err();
            assert!(err.contains("ALIAS_STALE_SEQUENCE"), "{err}");
        }
        let rows = read_alias_rows(dir.path()).unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(stored_alias_sequence(&rows, "alice", &addr), Some(5));
        // Higher sequences replace the row; other aliases / identities are independent.
        save_alias_claim(dir.path(), &signed_claim(&id, "alice", 6)).unwrap();
        save_alias_claim(dir.path(), &signed_claim(&id, "bob", 1)).unwrap();
        save_alias_claim(dir.path(), &signed_claim(&ident(0x0b), "alice", 1)).unwrap();
        let rows = read_alias_rows(dir.path()).unwrap();
        assert_eq!(stored_alias_sequence(&rows, "alice", &addr), Some(6));
        assert_eq!(stored_alias_sequence(&rows, "bob", &addr), Some(1));
        assert_eq!(stored_alias_sequence(&rows, "carol", &addr), None);
        assert_eq!(rows.len(), 3);
    }

    /// Privacy pack PP.6: in a sealed profile the CLI's own stores are
    /// sealed (the alias claims, RMS1 kind 26; each incoming contact
    /// request, kind 28) and read back; an alias store this process cannot
    /// open is refused, never written over.
    #[test]
    fn the_cli_stores_are_sealed_in_a_sealed_profile() {
        if !lab_hist_key() {
            return;
        }
        let dir = sealed_book();
        let dd = dir.path();
        let id = ident(0x0a);
        save_alias_claim(dd, &signed_claim(&id, "alice", 5)).unwrap();
        let raw = std::fs::read(alias_store_path(dd)).unwrap();
        assert!(raven_core::at_rest::is_sealed(&raw) && raw[5] == 26);
        assert!(!String::from_utf8_lossy(&raw).contains(&id.address()));
        let rows = read_alias_rows(dd).unwrap();
        assert_eq!(
            stored_alias_sequence(&rows, "alice", &id.address()),
            Some(5)
        );
        assert_eq!(load_alias_store(dd, now_ms()).len(), 1);
        raven_core::at_rest::forget_cached_keys(dd);
        let err = save_alias_claim(dd, &signed_claim(&id, "alice", 6)).unwrap_err();
        assert!(err.contains("alias_claims.json"), "{err}");
        assert_eq!(std::fs::read(alias_store_path(dd)).unwrap(), raw);
        assert_eq!(
            load_alias_store(dd, now_ms()).len(),
            0,
            "unreadable reads empty"
        );
        raven_core::at_rest::keys_load_with(dd, raven_core::at_rest::MigratePolicy::Allow).unwrap();
        let outer = RavenContactRequestV1 {
            request_id: [0x3c; 16],
            recipient_raven_id: id.address(),
            created_at: 1,
            expires_at: u64::MAX,
            ciphertext: vec![7; 40],
            sender_authentication: [0; 64],
            sender_pub: ident(0x0b).public_key_bytes(),
        };
        persist_inbox_wire(dd, &outer).unwrap();
        let path = contact_inbox_dir(dd).join(format!("{}.wire", hex::encode([0x3c; 16])));
        let raw = std::fs::read(&path).unwrap();
        assert!(raven_core::at_rest::is_sealed(&raw) && raw[5] == 28);
        let plain =
            raven_core::at_rest::load_bytes(dd, &path, raven_core::at_rest::Kind::ContactInbox)
                .unwrap()
                .unwrap();
        assert_eq!(&plain[..], &outer.encode_wire().unwrap()[..]);
    }

    /// Privacy pack PP.6: removing a contact deletes its send lock file (the
    /// keyed name, and an older build's hex name) and asks for the next
    /// data-key rotation; no lock file names a friend's key.
    #[test]
    fn contact_removal_leaves_no_lock_file_and_asks_for_a_rotation() {
        if !lab_hist_key() {
            return;
        }
        let dir = sealed_book();
        let dd = dir.path();
        let alice = ident(0x0a).public_key_bytes();
        let bob = ident(0x0b).public_key_bytes();
        let send_locks = || -> Vec<String> {
            let mut names: Vec<String> = std::fs::read_dir(dd)
                .unwrap()
                .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
                .filter(|n| n.starts_with(".send_"))
                .collect();
            names.sort();
            names
        };
        for peer in [&alice, &bob] {
            drop(
                raven_core::outbox::PeerSendLock::acquire_within(dd, peer, Duration::ZERO).unwrap(),
            );
        }
        // An older build's lock name for Alice too.
        drop(
            raven_core::DataDirLock::acquire_within(
                dd,
                &raven_core::outbox::PeerSendLock::legacy_file_name(&alice),
                Duration::ZERO,
            )
            .unwrap(),
        );
        assert_eq!(send_locks().len(), 3);
        assert!(!raven_core::privacy::rotation_due(dd));
        cmd_contact_remove(dd, Some("alice"), None, None, true).unwrap();
        assert_eq!(
            send_locks(),
            [raven_core::outbox::PeerSendLock::file_name(dd, &bob).unwrap()]
        );
        assert!(raven_core::privacy::rotation_due(dd));
        for name in send_locks() {
            assert!(!name.contains(&hex::encode(bob)), "{name}");
        }
    }

    /// An address on an interface that is up, as `netifs::read` lists it.
    fn lan_addr(ifname: &str, ip: &str) -> LocalAddr {
        LocalAddr {
            ifname: ifname.into(),
            ip: ip.parse().unwrap(),
            prefix: 24,
            up: true,
            loopback: false,
            point_to_point: false,
            virtual_net: false,
            scope_id: 0,
            index: 0,
            multicast: true,
            broadcast: true,
        }
    }

    #[test]
    fn listen_tip_lists_every_lan_address_hotspot_first() {
        // As this computer lists them: the hotspot comes first however the
        // system orders it; a VPN and Apple's peer-to-peer Wi-Fi never show.
        let read = vec![
            lan_addr("en0", "192.168.1.20"),
            LocalAddr {
                point_to_point: true,
                ..lan_addr("utun3", "10.8.0.2")
            },
            lan_addr("awdl0", "192.168.9.9"),
            lan_addr("en5", "169.254.12.3"),
            lan_addr("bridge100", "10.42.0.1"),
            lan_addr("en0", "fd00::7"),
        ];
        let lan = netifs::for_friends(read);
        let FriendTip::Addresses { heading, rows } = lan_tip(7420, &lan) else {
            panic!("{lan:?}");
        };
        assert_eq!(
            heading,
            "Tell your friend one of these addresses (this computer, port 7420):"
        );
        assert_eq!(
            rows,
            [
                "  10.42.0.1:7420       (your hotspot)",
                "  192.168.1.20:7420    (Wi-Fi or cable: en0)",
                "  169.254.12.3:7420    (a direct cable)",
                "  [fd00::7]:7420       (Wi-Fi or cable: en0)",
            ]
        );
        // A Windows hotspot by its address, whatever the adapter is called;
        // an adapter's name is printed only once made safe for a terminal.
        let FriendTip::Addresses { rows, .. } = lan_tip(
            7424,
            &[
                lan_addr("Wi-Fi 2", "192.168.137.1"),
                lan_addr("Ethernet\u{1b}[2J", "192.168.1.30"),
            ],
        ) else {
            panic!("addresses");
        };
        assert_eq!(rows[0], "  192.168.137.1:7424    (your hotspot)");
        assert!(
            rows[1].starts_with("  192.168.1.30:7424     (Wi-Fi or cable: Ethernet"),
            "{:?}",
            rows[1]
        );
        assert!(!rows[1].contains('\u{1b}'), "{:?}", rows[1]);
        // A virtual machine's bridge (Apple's vmnet on bridge100) is never
        // "your hotspot" and comes after the Wi-Fi (D-interfaces-texts-1).
        let lan = netifs::for_friends(vec![
            lan_addr("bridge100", "192.168.64.1"),
            lan_addr("en0", "192.168.0.16"),
        ]);
        let FriendTip::Addresses { rows, .. } = lan_tip(7420, &lan) else {
            panic!("{lan:?}");
        };
        assert_eq!(
            rows,
            [
                "  192.168.0.16:7420    (Wi-Fi or cable: en0)",
                "  192.168.64.1:7420    (virtual network: bridge100)",
            ]
        );
        // With nothing but virtual networks up, this computer is on none.
        let only_vm = netifs::for_friends(vec![
            lan_addr("bridge100", "192.168.64.1"),
            lan_addr("docker0", "172.17.0.1"),
        ]);
        assert_eq!(lan_tip(7420, &only_vm), FriendTip::NoNetwork);
        // On no network: how to get on one, and never a placeholder.
        assert_eq!(lan_tip(7420, &[]), FriendTip::NoNetwork);
        assert_eq!(
            NO_NETWORK_TIP,
            "This computer isn't on any network right now. Join a Wi-Fi, make a hotspot, or \
             connect a cable, then run `ash listen` again."
        );
    }

    /// The hint a send with no address for its contact prints names where
    /// friends really reach this computer: the running service's listener,
    /// else where a send would start one, never a fixed 7420; and says when
    /// they can't (D-interfaces-texts-6).
    #[test]
    fn the_no_address_hint_tells_where_this_computer_listens() {
        let svc = |receiving: bool, on: Option<&str>| ProfileService {
            receiving,
            lan_listen: on.map(str::to_owned),
            pid: Some(4242),
        };
        let a = |s: &str| s.parse::<std::net::SocketAddr>().unwrap();
        let cannot = |r: Result<std::net::SocketAddr, String>| {
            let text = r.unwrap_err();
            assert!(
                text.starts_with("Friends cannot reach this computer now"),
                "{text}"
            );
            text
        };
        // A second profile's service on 7424: its port, not the other one's.
        assert_eq!(
            unresolved_hint_listen(Some(&svc(true, Some("0.0.0.0:7424"))), None),
            Ok(a("0.0.0.0:7424"))
        );
        assert_eq!(
            unresolved_hint_listen(
                Some(&svc(true, Some("192.168.1.20:7420"))),
                Some("0.0.0.0:7424")
            ),
            Ok(a("192.168.1.20:7420")),
            "the running service wins over the setting"
        );
        // The installed agent on this computer only, or the outbound-only
        // setting: friends can't reach it.
        let local = cannot(unresolved_hint_listen(
            Some(&svc(true, Some("127.0.0.1:7420"))),
            None,
        ));
        assert!(
            local.contains("127.0.0.1:7420, this computer only"),
            "{local}"
        );
        let outbound = cannot(unresolved_hint_listen(None, Some("127.0.0.1:0")));
        assert!(outbound.contains("this computer only"), "{outbound}");
        cannot(unresolved_hint_listen(None, Some("0.0.0.0:0")));
        cannot(unresolved_hint_listen(Some(&svc(false, None)), None));
        // None runs: where a send would start one.
        assert_eq!(
            unresolved_hint_listen(None, Some(" 0.0.0.0:7424 ")),
            Ok(a("0.0.0.0:7424"))
        );
        assert_eq!(unresolved_hint_listen(None, None), Ok(a("0.0.0.0:7420")));
        // An older service that does not say where.
        assert_eq!(
            unresolved_hint_listen(Some(&svc(true, None)), Some("0.0.0.0:7425")),
            Ok(a("0.0.0.0:7425"))
        );
        // What the friend is told: every address with that port.
        let lan = [lan_addr("en0", "192.168.1.20")];
        let FriendTip::Addresses { heading, rows } = friend_tip(a("0.0.0.0:7424"), &lan) else {
            panic!("addresses");
        };
        assert!(heading.contains("port 7424"), "{heading}");
        assert!(rows[0].contains("192.168.1.20:7424"), "{rows:?}");
        // raven-node's own words reach the terminal only made safe.
        let hostile = cannot(unresolved_hint_listen(
            Some(&svc(true, Some("127.0.0.1:7420\u{1b}[2J"))),
            None,
        ));
        assert!(!hostile.contains('\u{1b}'), "{hostile:?}");
    }

    /// Linux and Windows used to print `<your-LAN-IP>`: every system now
    /// lists the addresses it reads, or says it is on no network.
    #[test]
    fn the_listen_tip_never_prints_a_placeholder() {
        let lan = netifs::lan_addresses_for_friends();
        let tips = [lan_tip(7420, &lan), lan_tip(7420, &[])];
        for tip in &tips {
            let text = match tip {
                FriendTip::Addresses { heading, rows } => format!("{heading}\n{}", rows.join("\n")),
                FriendTip::NoNetwork => NO_NETWORK_TIP.to_owned(),
            };
            assert!(!text.contains('<') && !text.contains("LAN-IP"), "{text}");
        }
        // Every address read is listed, with its port.
        if let FriendTip::Addresses { rows, .. } = &tips[0] {
            assert_eq!(rows.len(), lan.len());
            for (row, a) in rows.iter().zip(&lan) {
                let dial = std::net::SocketAddr::new(a.ip, 7420).to_string();
                assert!(row.trim_start().starts_with(&dial), "{row}");
            }
        }
    }

    #[test]
    fn pick_is_one_based_and_never_clamps_to_the_first_candidate() {
        assert_eq!(pick_index(1, 3), Some(0));
        assert_eq!(pick_index(3, 3), Some(2));
        assert_eq!(pick_index(0, 3), None);
        assert_eq!(pick_index(4, 3), None);
        assert_eq!(pick_index(1, 0), None);
    }

    #[test]
    fn re_adding_a_contact_keeps_its_labels_and_pin() {
        let dir = tempfile::tempdir().unwrap();
        seed_book(dir.path());
        let a = ident(0x0a);
        let a_hex = hex::encode(a.public_key_bytes());
        let find = |dir: &Path| {
            load_contacts(dir)
                .unwrap()
                .into_iter()
                .find(|c| c.pub_hex == a_hex)
                .unwrap()
        };
        // The documented dial-refresh workflow: only address + key + dial given.
        add_contact(
            dir.path(),
            &a.address(),
            &a_hex,
            "",
            "",
            None,
            "192.168.1.31:7420",
        )
        .unwrap();
        let alice = find(dir.path());
        assert_eq!(alice.petname, "Alice");
        assert_eq!(alice.public_tag, "alice");
        assert_eq!(alice.alias, "alice");
        assert!(alice.pinned);
        assert_eq!(alice.lan_dial, "192.168.1.31:7420");
        assert_eq!(load_contacts(dir.path()).unwrap().len(), 2);
        // An explicit petname still overrides; the omitted tag is kept.
        add_contact(dir.path(), &a.address(), &a_hex, "Alice B", "", None, "").unwrap();
        let alice = find(dir.path());
        assert_eq!(alice.petname, "Alice B");
        assert_eq!(alice.public_tag, "alice");
        assert_eq!(alice.lan_dial, "192.168.1.31:7420");
        // A petname-only contact stays petname-only.
        let b = ident(0x0b);
        add_contact(
            dir.path(),
            &b.address(),
            &hex::encode(b.public_key_bytes()),
            "",
            "",
            None,
            "",
        )
        .unwrap();
        let book = load_contacts(dir.path()).unwrap();
        let bob = book.iter().find(|c| c.petname == "Bob").unwrap();
        assert_eq!(bob.public_tag, "");
        assert!(!bob.pinned);
    }

    #[test]
    fn lone_at_sign_selects_nobody() {
        let a = ident(0x0a);
        let b = ident(0x0b);
        let book = vec![book_row(&a, "Alice", "alice"), book_row(&b, "Bob", "")];
        for q in ["@", "@@", " @ "] {
            assert!(resolve_tag_contacts(&book, q).is_empty(), "{q:?}");
            assert!(resolve_alias_contacts(&book, q).is_empty(), "{q:?}");
            assert_eq!(pick_send_contact(&book, q), SendPick::NoMatch, "{q:?}");
        }
        // Real tags still resolve.
        assert_eq!(resolve_tag_contacts(&book, "@alice").len(), 1);
        assert_eq!(pick_send_contact(&book, "@Alice"), SendPick::One(0));
        // `ash send --contact @` must not reach the petname-only contact.
        let dir = tempfile::tempdir().unwrap();
        save_contacts(dir.path(), &book).unwrap();
        let err = resolve_send_target(dir.path(), "@", "", "", "127.0.0.1:0", CarrierChoice::Auto)
            .unwrap_err();
        assert!(err.contains("no contact for"), "{err}");
    }

    /// G4: `--peer host:port` is an address the user typed (an auto send then
    /// records LAN); a `--contact` target is not, however few routes it has.
    #[test]
    fn only_a_peer_target_is_an_explicit_dial() {
        let dir = tempfile::tempdir().unwrap();
        seed_book(dir.path());
        let alice = hex::encode(ident(0x0a).public_key_bytes());
        let peer = resolve_send_target(
            dir.path(),
            "",
            "127.0.0.1:7420",
            &alice,
            "127.0.0.1:0",
            CarrierChoice::Auto,
        )
        .unwrap();
        assert!(peer.explicit_dial);
        assert_eq!(peer.routes, vec![lan_route("127.0.0.1:7420")]);
        let contact = without_nearby(
            resolve_send_target(
                dir.path(),
                "@alice",
                "",
                "",
                "127.0.0.1:0",
                CarrierChoice::Auto,
            )
            .unwrap(),
        );
        assert!(!contact.explicit_dial);
        assert_eq!(
            contact.routes.len(),
            1,
            "one LAN route: {:?}",
            contact.routes
        );
        assert_eq!(contact.routes[0].carrier, pair_init_lab::DialCarrier::Lan);
    }

    /// Hiding the IP from one contact while the friend relay is on says
    /// what it cannot cover: a contact both share who uses the relay names
    /// its address (this computer's IP) to its own contacts.
    #[test]
    fn hide_ip_warns_while_the_friend_relay_is_on() {
        let dir = tempfile::tempdir().unwrap();
        assert_eq!(friend_relay_hide_ip_note(dir.path(), "Bob"), None);
        let mut policy = NodePolicy {
            relay_offer: Some(false),
            ..NodePolicy::default()
        };
        save_policy(dir.path(), &policy).unwrap();
        assert_eq!(friend_relay_hide_ip_note(dir.path(), "Bob"), None);
        policy.relay_offer = Some(true);
        save_policy(dir.path(), &policy).unwrap();
        let note = friend_relay_hide_ip_note(dir.path(), "Bob").expect("the relay is on");
        assert!(
            note.contains("Bob can still learn that address through a contact you share"),
            "{note}"
        );
        assert!(note.contains("raven relay offer off"), "{note}");
        assert!(note.contains("It no longer lets Bob use it"), "{note}");
    }

    /// `raven node hide-ip on|off` says that the friend relay stops while
    /// hide my IP is on for everyone, and starts again after, when it has
    /// consent; nothing otherwise.
    #[test]
    fn node_hide_ip_says_the_friend_relay_stops_and_starts_again() {
        let mut policy = NodePolicy::default();
        for relay_offer in [None, Some(false)] {
            policy.relay_offer = relay_offer;
            assert_eq!(node_hide_ip_relay_note(&policy, true), None);
            assert_eq!(node_hide_ip_relay_note(&policy, false), None);
        }
        policy.relay_offer = Some(true);
        let on = node_hide_ip_relay_note(&policy, true).unwrap();
        assert!(on.contains("your friend relay stops"), "{on}");
        assert!(on.contains("`raven node hide-ip off`"), "{on}");
        let off = node_hide_ip_relay_note(&policy, false).unwrap();
        assert!(off.contains("starts again"), "{off}");
    }

    /// Hide my IP for everyone (`raven node hide-ip on`) holds for `raven
    /// send` whatever the route hints gate: no Internet direct dial to any
    /// contact, as raven-node plans it. A contact's own row hides it alone.
    #[test]
    fn node_hide_ip_holds_for_send_whatever_the_route_hints_gate() {
        let dir = tempfile::tempdir().unwrap();
        let book = seed_book(dir.path());
        let alice = book.iter().find(|c| c.petname == "Alice").unwrap();
        assert!(!hides_ip_from(dir.path(), alice));
        let mut policy = NodePolicy {
            hide_ip: true,
            ..NodePolicy::default()
        };
        save_policy(dir.path(), &policy).unwrap();
        assert!(hides_ip_from(dir.path(), alice), "every contact");
        policy.hide_ip = false;
        save_policy(dir.path(), &policy).unwrap();
        let mut hidden = alice.clone();
        hidden.hide_ip = true;
        assert!(hides_ip_from(dir.path(), &hidden), "its own row");
    }

    /// P2.R1 for `raven send`: a LAN route it plans from what was learned
    /// (here where the contact last reached us from) is dialled now but
    /// never recorded for raven-node's outbox, whose worker plans it again
    /// at every attempt through its own on-link filter; a recorded copy
    /// would be dialled on every retry, on any network. The book's route is
    /// recorded as before.
    #[test]
    fn a_send_records_no_learned_lan_route() {
        use raven_core::outbox::{OutboxCarrier, OutboxRoute};
        let dir = tempfile::tempdir().unwrap();
        seed_book(dir.path());
        let alice = ident(0x0a).public_key_bytes();
        raven_core::lan_seen::record_contact_seen(
            dir.path(),
            &alice,
            "192.168.1.33".parse().unwrap(),
            None,
            now_ms(),
        )
        .unwrap();
        let target = without_nearby(
            resolve_send_target(
                dir.path(),
                "@alice",
                "",
                "",
                "127.0.0.1:0",
                CarrierChoice::Auto,
            )
            .unwrap(),
        );
        assert_eq!(
            target.routes,
            vec![
                lan_route("192.168.1.20:7420"),
                lan_route("192.168.1.33:7420")
            ]
        );
        assert_eq!(target.unrecorded, ["192.168.1.33:7420"]);
        assert_eq!(target.learned_lan_dials, ["192.168.1.33:7420"]);
        let id = [7u8; 16];
        pair_init_lab::OutboxHandoff::new(
            dir.path(),
            &target.routes,
            alice,
            Some(raven_core::outbox::CarrierChoice::Auto),
        )
        .leaving_out(&target.unrecorded)
        .record(&id, now_ms() + 3_600_000);
        let records = raven_core::outbox::object_route_records(dir.path(), now_ms()).unwrap();
        assert_eq!(
            records[&id].routes,
            vec![OutboxRoute {
                carrier: OutboxCarrier::Lan,
                dial: "192.168.1.20:7420".into(),
            }]
        );
        assert_eq!(records[&id].choice, raven_core::outbox::CarrierChoice::Auto);
    }

    /// Cutoff F7: Bob was added from an invite line (no address saved) and
    /// reached us from 192.168.1.44 over a link that pinned his Noise
    /// static (M0). A reply goes there on the default LAN port as a learned
    /// route: dialled now, never recorded, saved once it reached him. No pin
    /// or nothing learned: the no-address refusal, as before.
    #[test]
    fn a_reply_to_an_invite_only_contact_goes_to_its_link_ip() {
        let dir = tempfile::tempdir().unwrap();
        let d = dir.path();
        let book = seed_book(d);
        let bob = book.iter().find(|c| c.petname == "Bob").unwrap();
        let alice = book.iter().find(|c| c.petname == "Alice").unwrap();
        let key = ident(0x0b).public_key_bytes();
        let port = raven_core::lan_gate::lab_default_lan_port().unwrap_or(DEFAULT_LAN_PORT);
        let guess = format!("192.168.1.44:{port}");
        let refused = |e: &String| e.contains("has no reachable lan_dial");
        let auto = CarrierChoice::Auto;
        assert!(
            unsaved_lan_routes(d, bob, auto, true).is_empty(),
            "nothing seen"
        );
        raven_core::lan_seen::record_contact_seen(
            d,
            &key,
            "192.168.1.44".parse().unwrap(),
            None,
            now_ms(),
        )
        .unwrap();
        assert!(unsaved_lan_routes(d, bob, auto, true).is_empty(), "no pin");
        let pin_key = raven_core::lan_noise_pin::PinKey::derive(&raven_core::Identity::from_seed(
            &[0xC0; 32],
        ));
        raven_core::lan_noise_pin::record(d, &pin_key, &key, &[0x51; 32]).unwrap();
        let unsaved = unsaved_lan_routes(d, bob, auto, true);
        assert_eq!(unsaved, [guess.as_str()]);
        assert_eq!(
            unsaved_lan_routes(d, bob, CarrierChoice::Lan, true),
            [guess.as_str()]
        );
        assert!(unsaved_lan_routes(d, bob, CarrierChoice::Internet, true).is_empty());
        assert!(
            unsaved_lan_routes(d, alice, auto, true).is_empty(),
            "Alice has an address saved"
        );
        assert_eq!(
            plan_contact_routes_with(d, bob, auto, None, false, false, &unsaved, &[]),
            Ok((vec![lan_route(&guess)], None))
        );
        // An address given for this send still wins.
        assert_eq!(
            plan_contact_routes_with(
                d,
                bob,
                auto,
                Some("10.9.9.9:7420".into()),
                false,
                false,
                &unsaved,
                &[]
            )
            .unwrap()
            .0,
            vec![lan_route("10.9.9.9:7420")]
        );
        assert!(
            plan_contact_routes_with(d, bob, auto, None, false, false, &[], &[])
                .is_err_and(|e| refused(&e))
        );
        // The send itself, by this run's gates.
        let hints = raven_core::route_hints::route_hints_live();
        let target = resolve_send_target(d, "Bob", "", "", "127.0.0.1:0", auto);
        if raven_core::outbox::default_port_guess_live() && !hints {
            let target = target.unwrap();
            assert_eq!(target.routes, vec![lan_route(&guess)]);
            assert_eq!(target.unrecorded, [guess.as_str()]);
            assert_eq!(target.learned_lan_dials, [guess.as_str()]);
            assert!(target.lan_unsaved);
        } else if !hints {
            assert!(unsaved_lan_routes(d, bob, auto, false).is_empty());
            assert!(target.is_err_and(|e| refused(&e)));
        }
    }

    /// Phase 3 P3.11: where the LAN beacon found a contact leads its LAN
    /// routes, the saved address right after (once, when it was found there
    /// too). A contact with no LAN address saved (an invite line, a card
    /// without one) gets its LAN route this way instead of the no-address
    /// refusal, with `--carrier lan` too; a send that does not allow LAN
    /// takes no find.
    #[test]
    fn beacon_routes_are_planned_first_and_stand_in_for_a_missing_lan_address() {
        let dir = tempfile::tempdir().unwrap();
        let d = dir.path();
        let book = seed_book(d);
        let alice = book.iter().find(|c| c.petname == "Alice").unwrap();
        let bob = book.iter().find(|c| c.petname == "Bob").unwrap();
        let found = [
            "192.168.1.77:7499".to_string(),
            "[fe80::1%en0]:7499".to_string(),
        ];
        let auto = CarrierChoice::Auto;
        let plan = |c: &Contact, choice, found: &[String]| {
            plan_contact_routes_with(d, c, choice, None, true, false, &[], found)
        };
        assert_eq!(
            plan(alice, auto, &found),
            Ok((
                vec![
                    lan_route(&found[0]),
                    lan_route(&found[1]),
                    lan_route("192.168.1.20:7420")
                ],
                None
            ))
        );
        assert_eq!(
            plan(alice, auto, &["192.168.1.20:7420".to_string()])
                .unwrap()
                .0,
            vec![lan_route("192.168.1.20:7420")],
            "found at the saved address"
        );
        // E1: said once, as the saved address the beacon found; a find
        // elsewhere is said as not saved.
        assert_eq!(
            found_label("192.168.1.20:7420", Some("192.168.1.20:7420"), "Alice"),
            "saved · found on your network now · Alice"
        );
        assert_eq!(
            found_label(&found[0], Some("192.168.1.20:7420"), "Alice"),
            "found on your network now · Alice · not saved"
        );
        assert_eq!(
            found_label(&found[0], None, "Bob"),
            "found on your network now · Bob · not saved"
        );
        let refused = |e: &String| e.contains("has no reachable lan_dial");
        assert!(plan(bob, auto, &[]).is_err_and(|e| refused(&e)));
        for choice in [auto, CarrierChoice::Lan] {
            assert_eq!(
                plan(bob, choice, &found).unwrap().0,
                vec![lan_route(&found[0]), lan_route(&found[1])],
                "{choice:?}"
            );
        }
        assert!(plan(alice, CarrierChoice::Internet, &found)
            .is_err_and(|e| e.contains("has no Internet address saved")));
    }

    /// The nearby search a send asks raven-node for (IPC `LanLocate`): it
    /// lets the node wait up to a second, or not at all when the contact
    /// reached this computer on the LAN in the last 2 minutes, and takes at
    /// most two local dial strings, IPv4 first. An older raven-node
    /// (`IPC_FRAME`), none, a refusal or any other answer: no find and no
    /// error. A send that does not allow LAN asks nothing.
    #[test]
    fn a_send_asks_the_beacon_and_an_older_daemon_gives_no_route() {
        let dir = tempfile::tempdir().unwrap();
        let d = dir.path();
        let book = seed_book(d);
        let bob = book.iter().find(|c| c.petname == "Bob").unwrap();
        let ask = |fresh: bool, answer: Result<IpcResponse, String>| {
            let mut asked = None;
            let found = beacon_routes_with(bob, fresh, |req, timeout| {
                asked = Some((req.clone(), timeout));
                answer
            });
            (found, asked)
        };
        let located = |dials: &[&str]| {
            Ok(IpcResponse::LanLocated {
                v: IPC_VERSION,
                dials: dials.iter().map(|d| d.to_string()).collect(),
            })
        };
        let request = |wait_ms: u32| IpcRequest::LanLocate {
            v: IPC_VERSION,
            peer_pub_hex: bob.pub_hex.to_ascii_lowercase(),
            wait_ms,
        };
        let (found, asked) = ask(
            false,
            located(&[
                "203.0.113.9:7499",
                "[fe80::1%en0]:7499",
                "192.168.1.77:7499",
                "10.0.0.7:7499",
            ]),
        );
        assert_eq!(found, ["192.168.1.77:7499", "10.0.0.7:7499"]);
        // The wait covers one find under the shaped sends (Phase 6 review
        // traffic-3), and the node waits as long at most.
        assert_eq!(asked, Some((request(2_000), Duration::from_secs(4))));
        let (found, asked) = ask(true, located(&["[fe80::1%en0]:7499"]));
        assert_eq!(found, ["[fe80::1%en0]:7499"]);
        assert_eq!(asked, Some((request(0), Duration::from_secs(2))));
        for answer in [
            Ok(IpcResponse::Error {
                v: IPC_VERSION,
                code: "IPC_FRAME".into(),
                message: "unknown variant `lan_locate`".into(),
            }),
            Ok(IpcResponse::Error {
                v: IPC_VERSION,
                code: "NOT_A_CONTACT".into(),
                message: "no nearby search: not one of your contacts".into(),
            }),
            Ok(IpcResponse::Pong { v: IPC_VERSION }),
            Err("raven-node is not running".into()),
        ] {
            assert!(ask(false, answer.clone()).0.is_empty(), "{answer:?}");
        }
        // Fresh: Bob reached us on the LAN a minute ago.
        let key = parse_pub_hex(&bob.pub_hex).unwrap();
        assert!(!lan_route_is_fresh(d, bob, now_ms()));
        let at = now_ms() - 60_000;
        raven_core::lan_seen::record_contact_seen(
            d,
            &key,
            "192.168.1.44".parse().unwrap(),
            None,
            at,
        )
        .unwrap();
        assert!(lan_route_is_fresh(d, bob, at + BEACON_FRESH_MS));
        assert!(!lan_route_is_fresh(d, bob, at + BEACON_FRESH_MS + 1));
        // No LAN in the send: nothing asked (no raven-node runs here, so
        // with the beacon's gate open an `auto` send finds nothing either).
        for choice in [
            CarrierChoice::Internet,
            CarrierChoice::P2p,
            CarrierChoice::Auto,
        ] {
            assert!(beacon_routes(d, bob, choice).is_empty(), "{choice:?}");
        }
    }

    /// `raven send --contact` with the LAN beacon (Phase 3 P3.11), by this
    /// run's gate (`RAVEN_LAB_LAN_BEACON`). Open: raven-node's finds go
    /// first, are dialled now, never recorded for the outbox and never saved
    /// to the contact, and nothing learned (here where Alice last reached
    /// us from) is planned with them; Bob, with no LAN address saved, gets
    /// his LAN route this way. Closed: raven-node is not asked.
    #[cfg(unix)]
    #[test]
    fn beacon_routes_are_inserted_first_and_never_saved() {
        use raven_core::outbox::{OutboxCarrier, OutboxRoute};
        let dir = ipc_client::test_support::short_tempdir();
        let d = dir.path();
        seed_book(d);
        let alice = ident(0x0a).public_key_bytes();
        let bob = ident(0x0b).public_key_bytes();
        raven_core::lan_seen::record_contact_seen(
            d,
            &alice,
            "192.168.1.33".parse().unwrap(),
            None,
            now_ms(),
        )
        .unwrap();
        let found = "192.168.1.77:7499";
        let asked = ipc_client::test_support::spawn_locate_server(
            &raven_core::default_socket_path(d),
            vec![found.to_string()],
        );
        let book = std::fs::read(d.join("contacts.json")).unwrap();
        let send = |contact: &str| {
            resolve_send_target(d, contact, "", "", "127.0.0.1:0", CarrierChoice::Auto)
                .map(without_nearby)
        };
        let target = send("@alice").unwrap();
        if !raven_core::lan_beacon_live() {
            assert_eq!(
                target.routes,
                [
                    lan_route("192.168.1.20:7420"),
                    lan_route("192.168.1.33:7420")
                ]
            );
            assert_eq!(asked.load(std::sync::atomic::Ordering::SeqCst), 0);
            return;
        }
        assert_eq!(
            target.routes,
            [lan_route(found), lan_route("192.168.1.20:7420")]
        );
        assert_eq!(target.unrecorded, [found]);
        assert!(target.learned_lan_dials.is_empty(), "never saved");
        let id = [9u8; 16];
        pair_init_lab::OutboxHandoff::new(
            d,
            &target.routes,
            alice,
            Some(raven_core::outbox::CarrierChoice::Auto),
        )
        .leaving_out(&target.unrecorded)
        .record(&id, now_ms() + 3_600_000);
        let records = raven_core::outbox::object_route_records(d, now_ms()).unwrap();
        assert_eq!(
            records[&id].routes,
            vec![OutboxRoute {
                carrier: OutboxCarrier::Lan,
                dial: "192.168.1.20:7420".into(),
            }],
            "never recorded"
        );
        let target = send("Bob").unwrap();
        assert_eq!(target.routes, [lan_route(found)]);
        assert_eq!(target.unrecorded, [found]);
        assert!(target.learned_lan_dials.is_empty() && !target.lan_unsaved);
        assert_eq!(target.pub_hex, hex::encode(bob));
        assert_eq!(asked.load(std::sync::atomic::Ordering::SeqCst), 2);
        assert_eq!(std::fs::read(d.join("contacts.json")).unwrap(), book);
    }

    #[test]
    fn env_dial_is_resolved_but_never_written_to_the_contact() {
        let dir = tempfile::tempdir().unwrap();
        seed_book(dir.path());
        let book = load_contacts(dir.path()).unwrap();
        let alice = book.iter().find(|c| c.petname == "Alice").unwrap();
        let bob = book.iter().find(|c| c.petname == "Bob").unwrap();
        let before = std::fs::read(dir.path().join("contacts.json")).unwrap();
        // No saved dial: the env dial is used, flagged "not saved", and the
        // book is untouched (it used to be stamped onto whoever was picked).
        assert_eq!(
            resolve_or_reuse_lan_dial_with(dir.path(), bob, Some("10.9.9.9:7420".into())),
            Some((ResolvedLanPeer::Dial("10.9.9.9:7420".into()), true))
        );
        assert_eq!(
            std::fs::read(dir.path().join("contacts.json")).unwrap(),
            before
        );
        // A saved dial wins (documented) and is not flagged for saving.
        assert_eq!(
            resolve_or_reuse_lan_dial_with(dir.path(), alice, Some("10.9.9.9:7420".into())),
            Some((ResolvedLanPeer::Dial("192.168.1.20:7420".into()), false))
        );
        assert_eq!(resolve_or_reuse_lan_dial_with(dir.path(), bob, None), None);
    }

    #[test]
    fn forward_queue_status_does_not_hide_failures() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("forward_queue.sqlite");
        assert_eq!(forward_queue_view(&path), ForwardQueueView::Absent);
        assert!(forward_queue_line(&ForwardQueueView::Absent).contains("no queue file"));
        ForwardQueue::open(&path).unwrap();
        assert_eq!(
            forward_queue_view(&path),
            ForwardQueueView::Counts {
                pending: 0,
                total: 0
            }
        );
        assert_eq!(
            forward_queue_line(&ForwardQueueView::Counts {
                pending: 2,
                total: 5
            }),
            "2 pending / 5 total"
        );
        // A queue that exists but cannot be opened is NOT "0 pending / 0 total".
        std::fs::write(&path, b"this is not a sqlite database, just text padding").unwrap();
        let view = forward_queue_view(&path);
        assert!(matches!(view, ForwardQueueView::Unavailable(_)), "{view:?}");
        let line = forward_queue_line(&view);
        assert!(line.contains("unavailable"), "{line}");
        assert!(!line.contains("0 pending"), "{line}");
    }

    #[test]
    fn stdin_message_is_bounded_and_trimmed() {
        assert_eq!(
            read_message_text(&b"hello\r\n\n"[..], 100).unwrap(),
            "hello"
        );
        assert_eq!(
            read_message_text(&b"hi\nthere\n"[..], 100).unwrap(),
            "hi\nthere"
        );
        assert_eq!(read_message_text(&b""[..], 100).unwrap(), "");
        // Exactly the limit (plus the trailing newline) fits; one byte more does not.
        let exact = format!("{}\n", "a".repeat(100));
        assert_eq!(read_message_text(exact.as_bytes(), 100).unwrap().len(), 100);
        let over = "a".repeat(101);
        let err = read_message_text(over.as_bytes(), 100).unwrap_err();
        assert!(err.contains("too large"), "{err}");
        // An endless pipe stops at the cap instead of being buffered forever.
        let err = read_message_text(std::io::repeat(b'a'), 100).unwrap_err();
        assert!(err.contains("too large"), "{err}");
        assert_eq!(
            read_message_text(&[0xff, 0xfe][..], 100).unwrap_err(),
            "failed to read message from stdin"
        );
    }

    #[test]
    fn node_flag_keeps_unnamed_flags_and_repairs_an_unreadable_policy() {
        let dir = tempfile::tempdir().unwrap();
        // A readable policy: only the named flag changes.
        let p = NodePolicy {
            bridge: false,
            store: true,
            relay: true,
            endpoint: true,
            auto_policy: true,
            internet_listen: String::new(),
            ..NodePolicy::default()
        };
        save_policy(dir.path(), &p).unwrap();
        set_node_flag(dir.path(), "bridge", true);
        let got = try_load_policy(dir.path()).unwrap();
        assert!(got.bridge && got.store && got.relay);
        assert!(!got.auto_policy);
        // Unreadable policy: the command still repairs the file (fail-closed
        // base, only the named flag on) — and warns about the reset flags.
        std::fs::write(raven_core::node_policy::policy_path(dir.path()), "{broken").unwrap();
        set_node_flag(dir.path(), "bridge", true);
        let got = try_load_policy(dir.path()).unwrap();
        assert!(got.bridge && !got.store && !got.relay && !got.auto_policy);
    }

