    /// A-noise-pin-4: `raven doctor` reads the noise pin store while M0 is
    /// on and, when it exists but cannot be read (raven-node then dials no
    /// one), names the file and the fix. Nothing with the gate closed.
    #[test]
    fn doctor_names_an_unreadable_noise_pin_store() {
        let dir = tempfile::tempdir().unwrap();
        assert_eq!(doctor_noise_pin_line(dir.path(), false), None);
        assert_eq!(
            doctor_noise_pin_line(dir.path(), true).as_deref(),
            Some("lan_noise_pins: ok pinned=0")
        );
        let pin_key = raven_core::lan_noise_pin::PinKey::derive(&ident(0x0c));
        raven_core::lan_noise_pin::record(dir.path(), &pin_key, &[0x0b; 32], &[0x51; 32]).unwrap();
        assert_eq!(
            doctor_noise_pin_line(dir.path(), true).as_deref(),
            Some("lan_noise_pins: ok pinned=1")
        );
        let broken = tempfile::tempdir().unwrap();
        let file = broken
            .path()
            .join(raven_core::lan_noise_pin::NOISE_PIN_FILE);
        std::fs::create_dir(&file).unwrap();
        assert_eq!(doctor_noise_pin_line(broken.path(), false), None);
        let line = doctor_noise_pin_line(broken.path(), true).unwrap();
        assert!(line.starts_with("lan_noise_pins: UNREADABLE ("), "{line}");
        assert!(line.contains(&file.display().to_string()), "{line}");
        assert!(line.contains("connects to no contact"), "{line}");
        assert!(line.contains("move it aside"), "{line}");
        assert_eq!(line.lines().count(), 1, "{line}");
    }

    /// M0: removing a contact forgets the noise pin of its computer's key
    /// (a contact added again starts afresh); an address change keeps it,
    /// and so does every other contact's.
    #[test]
    fn contact_remove_forgets_the_noise_pin_but_an_address_change_keeps_it() {
        let dir = tempfile::tempdir().unwrap();
        seed_book(dir.path());
        let alice = ident(0x0a).public_key_bytes();
        let bob = ident(0x0b).public_key_bytes();
        let pin_key = raven_core::lan_noise_pin::PinKey::derive(&ident(0x0c));
        for peer in [&alice, &bob] {
            raven_core::lan_noise_pin::record(dir.path(), &pin_key, peer, &[0x51; 32]).unwrap();
        }
        let pinned = |peer: &[u8; 32]| {
            raven_core::lan_noise_pin::load_pin(dir.path(), peer)
                .unwrap()
                .is_some()
        };
        cmd_contact_set_dial(dir.path(), Some("@alice"), None, None, "192.168.1.31:7420").unwrap();
        assert!(pinned(&alice), "an address change keeps it");
        cmd_contact_remove(dir.path(), Some("alice"), None, None, true).unwrap();
        assert!(!pinned(&alice));
        assert!(pinned(&bob), "only Alice's");
    }

    /// A capability floor (Phase 6b P6.29) as raven-node keeps it: `floors`
    /// by contact key, in a plain profile.
    fn write_floors(dd: &Path, floors: &[(&[u8; 32], raven_core::capability_floor::Floor)]) {
        let floors: serde_json::Map<String, serde_json::Value> = floors
            .iter()
            .map(|(peer, floor)| (hex::encode(peer), serde_json::to_value(floor).unwrap()))
            .collect();
        std::fs::write(
            dd.join(raven_core::capability_floor::CAPABILITY_FLOOR_FILE),
            serde_json::json!({ "floors": floors }).to_string(),
        )
        .unwrap();
    }

    /// A floor with a session profile refused below it: an open downgrade.
    fn refused_floor() -> raven_core::capability_floor::Floor {
        raven_core::capability_floor::Floor {
            refused_profile: Some(1),
            ..raven_core::capability_floor::Floor::new(1)
        }
    }

    /// P6.29: removing a contact forgets its capability floor; every other
    /// contact's stays.
    #[test]
    fn contact_remove_forgets_the_capability_floor() {
        use raven_core::capability_floor::floor;
        let dir = tempfile::tempdir().unwrap();
        let dd = dir.path();
        seed_book(dd);
        let alice = ident(0x0a).public_key_bytes();
        let bob = ident(0x0b).public_key_bytes();
        write_floors(dd, &[(&alice, refused_floor()), (&bob, refused_floor())]);
        cmd_contact_remove(dd, Some("alice"), None, None, true).unwrap();
        assert_eq!(floor(dd, &alice), None);
        assert_eq!(floor(dd, &bob), Some(refused_floor()), "only Alice's");
    }

    /// P6.38: removing a contact forgets its pair seeds (it starts from the
    /// pair's fixed key when added again); every other contact's stay.
    #[test]
    fn contact_remove_forgets_the_pair_seeds() {
        use raven_core::pair_seed::{incoming, is_leader, outgoing, state, SeedEntry};
        let dir = tempfile::tempdir().unwrap();
        let dd = dir.path();
        seed_book(dd);
        let me = ident(0x0c).public_key_bytes();
        let alice = ident(0x0a).public_key_bytes();
        let bob = ident(0x0b).public_key_bytes();
        let offer = SeedEntry::new(1, [0x38; 32], 1);
        for peer in [&alice, &bob] {
            if is_leader(&me, peer) {
                outgoing(dd, &me, peer, 1, || [0x38; 32]).unwrap();
            } else {
                incoming(dd, &me, peer, Some(&offer), 1).unwrap();
            }
            assert!(state(dd, peer).is_some());
        }
        cmd_contact_remove(dd, Some("alice"), None, None, true).unwrap();
        assert!(state(dd, &alice).is_none());
        assert!(state(dd, &bob).is_some(), "only Alice's");
    }

    /// P6.29: after a match, an open downgrade in the contact's capability
    /// floor is lowered only after the security words and a typed `accept`
    /// (keyboard layout tolerated); the old code, another answer or no
    /// terminal lowers nothing, and with nothing open nothing is asked.
    #[test]
    fn contact_verify_lowers_a_floor_only_after_the_words_and_accept() {
        use raven_core::capability_floor::{floor, SetBy};
        let dir = tempfile::tempdir().unwrap();
        let dd = dir.path();
        let alice = ident(0x0a).public_key_bytes();
        write_floors(dd, &[(&alice, refused_floor())]);
        let words = words_text(&alice);
        let open = || floor(dd, &alice).unwrap().open_downgrade();
        offer_lower_floor(dd, "Alice", &alice, &words, false, None).unwrap();
        assert!(open(), "no terminal: only says how");
        let mut asked = false;
        let mut answer = || {
            asked = true;
            Some("accept".to_string())
        };
        let code = device_fingerprint_v1(&alice);
        offer_lower_floor(dd, "Alice", &alice, &code, false, Some(&mut answer)).unwrap();
        assert!(!asked && open(), "the old code is not enough");
        let reply = |text: Option<&'static str>| move || text.map(String::from);
        let mut never = || -> Option<String> { panic!("asked") };
        offer_lower_floor(
            dd,
            "Alice",
            &alice,
            &words,
            false,
            Some(&mut reply(Some("yes"))),
        )
        .unwrap();
        assert!(open());
        offer_lower_floor(dd, "Alice", &alice, &words, false, Some(&mut reply(None))).unwrap();
        assert!(open());
        offer_lower_floor(
            dd,
            "Alice",
            &alice,
            &words,
            false,
            Some(&mut reply(Some(" Accept "))),
        )
        .unwrap();
        let lowered = floor(dd, &alice).unwrap();
        assert!(!lowered.open_downgrade());
        assert_eq!(lowered.set_by, SetBy::User);
        offer_lower_floor(dd, "Alice", &alice, &words, false, Some(&mut never)).unwrap();
        // A contact without a floor: nothing asked, nothing written.
        let bob = ident(0x0b).public_key_bytes();
        offer_lower_floor(dd, "Bob", &bob, &words_text(&bob), false, Some(&mut never)).unwrap();
        assert_eq!(floor(dd, &bob), None);
        // P6.30: a capability downgrade alert open in the security ledger
        // (before the match resolved it) offers the same choice for a floor
        // with nothing open in it, under the same words and `accept`; a
        // contact without a floor is still never asked.
        write_floors(dd, &[(&alice, raven_core::capability_floor::Floor::new(1))]);
        offer_lower_floor(dd, "Alice", &alice, &words, false, Some(&mut never)).unwrap();
        let asked = std::cell::Cell::new(false);
        let mut accept = || {
            asked.set(true);
            Some("accept".to_string())
        };
        offer_lower_floor(dd, "Alice", &alice, &code, true, Some(&mut accept)).unwrap();
        assert!(!asked.get(), "the old code is not enough");
        offer_lower_floor(dd, "Alice", &alice, &words, true, Some(&mut accept)).unwrap();
        assert!(asked.get());
        assert_eq!(floor(dd, &alice).unwrap().set_by, SetBy::User);
        offer_lower_floor(dd, "Bob", &bob, &words_text(&bob), true, Some(&mut never)).unwrap();
        assert_eq!(floor(dd, &bob), None);
    }

    #[test]
    fn contact_unblock_reverses_a_block_and_refuses_unknown_keys() {
        let dir = tempfile::tempdir().unwrap();
        let peer = ident(0x0d);
        let peer_hex = hex::encode(peer.public_key_bytes());
        let mut blocks = BlockList::load_checked(dir.path()).unwrap();
        blocks.block(&peer_hex);
        blocks.save(dir.path()).unwrap();
        cmd_contact_unblock(dir.path(), &peer_hex).unwrap();
        assert!(!BlockList::load_checked(dir.path())
            .unwrap()
            .is_blocked(&peer_hex));
        let err = cmd_contact_unblock(dir.path(), &peer_hex).unwrap_err();
        assert!(err.contains("not on the block list"), "{err}");
        assert!(cmd_contact_unblock(dir.path(), "zz").is_err());
        // A corrupt list is never overwritten.
        let path = raven_core::chat_history::blocked_path(dir.path());
        std::fs::write(&path, "{broken").unwrap();
        let err = cmd_contact_unblock(dir.path(), &peer_hex).unwrap_err();
        assert!(err.contains("block list"), "{err}");
        assert_eq!(std::fs::read_to_string(&path).unwrap(), "{broken");
    }

