    /// The lab-profile warning follows the keystore backend switches: any of
    /// them set to `locked-file` in a debug build, nothing else.
    #[test]
    fn the_lab_warning_appears_only_with_a_locked_file_backend() {
        use std::ffi::OsString;
        assert!(!lab_backend_active_with(true, |_| None));
        for key in LAB_BACKEND_ENVS {
            let lab = |k: &str| (k == key).then(|| OsString::from("locked-file"));
            assert!(lab_backend_active_with(true, lab), "{key}");
            // A release build refuses the switch: no lab backend, no warning.
            assert!(!lab_backend_active_with(false, lab), "{key}");
            let other = |k: &str| (k == key).then(|| OsString::from("keychain"));
            assert!(!lab_backend_active_with(true, other), "{key}");
        }
        assert!(!lab_backend_active_with(true, |k| {
            (k == "RAVEN_KEYSTORE_BACKEND").then(|| OsString::from("locked-file"))
        }));
        // Every switch is one raven-core reads.
        let core = [
            include_str!("../../raven-core/src/identity_store.rs"),
            include_str!("../../raven-core/src/indexed_session_store.rs"),
            include_str!("../../raven-core/src/prekey_lifecycle.rs"),
            include_str!("../../raven-core/src/chat_history.rs"),
        ];
        for key in LAB_BACKEND_ENVS {
            assert!(
                core.iter().any(|src| src.contains(&format!("\"{key}\""))),
                "{key}"
            );
        }
        assert_eq!(
            LAB_BACKEND_KEY_LINE,
            "lab_backend: locked-file (keys unencrypted)"
        );
        assert!(LAB_BACKEND_WARNING.contains("unencrypted"));
        assert!(LAB_BACKEND_WARNING.ends_with("never for real messages."));
    }

