    /// Raven's own login item for `dd` in a lab folder, and the fake tools
    /// (they record what they are asked: no real login item is touched).
    #[cfg(unix)]
    fn login_lab(
        platform: node_control::Platform,
        dd: &Path,
        tmp: &Path,
        fail: bool,
    ) -> (node_control::LoginEnv, PathBuf) {
        let (tools, log) = node_control::tests::shims(tmp, fail);
        let root = tmp.join("items");
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(
            root.join(platform.item_file()),
            node_control::tests::fixture(platform, dd),
        )
        .unwrap();
        (
            node_control::LoginEnv::lab(platform, &root, &tools, 501),
            log,
        )
    }

    #[test]
    fn lock_texts_per_profile_type() {
        let keychain = lock_question(false, None);
        assert!(keychain.starts_with("Stop Raven now? Raven stops, and friends can't reach you"));
        assert!(keychain.contains(
            "Your Raven keys stay in this computer's keychain: anyone who can log in as you can \
             still open your chats. Lock your screen or log out too. [y/N] "
        ));
        assert!(keychain.ends_with("[y/N] "));
        let vault = lock_question(true, None);
        assert_eq!(
            vault,
            "Lock Raven now? Raven stops. Your chats can't be opened again without your \
             passphrase. Friends can't reach you until you start Raven again. [y/N] "
        );
        // A saved passphrase file (vault profiles: it unlocks them).
        let file = Path::new("/home/sam/.config/raven/keystore-passphrase");
        let saved = lock_question(true, Some(file));
        assert!(saved.starts_with("Lock Raven now?"), "{saved}");
        assert!(saved.contains(
            "\nYour passphrase is saved in a file on this computer \
             (/home/sam/.config/raven/keystore-passphrase). Anyone who can read your files can \
             unlock Raven with it."
        ));
        assert!(saved.ends_with("send and receive.\n[y/N] "), "{saved}");
        assert_eq!(
            lock_question(false, Some(file)),
            keychain,
            "no vault: no paragraph"
        );

        assert_eq!(lock_result_lines(true, None)[0], "Raven is locked.");
        assert_eq!(lock_result_lines(false, None)[0], "Raven is stopped.");
        assert_eq!(lock_result_lines(false, Some(true))[0], "Raven is stopped.");
        assert_eq!(lock_result_lines(true, Some(true))[0], "Raven is locked.");
        for vault in [false, true] {
            let lines = lock_result_lines(vault, Some(false));
            assert_eq!(lines[0], "Raven is stopped until you log in again.");
            assert_eq!(
                lines[1],
                "Run `raven unlock` to start it again. If Raven is open in another window, \
                 close it too. Clear your terminal too: its scrollback may show messages."
            );
        }
        // A service Raven didn't install for this profile.
        assert_eq!(
            lock_not_stopped_text("kill 42", true),
            "Raven is run by a service Raven didn't install, so Lock can't stop it: kill 42. \
             Lock your screen or log out."
        );
        let still = lock_not_stopped_text("kill 42", false);
        assert!(
            still.starts_with("Raven is still running, so it isn't locked."),
            "{still}"
        );
        assert!(still.contains("(kill 42)") && still.contains("lock your screen or log out"));
        assert!(LOGIN_ITEM_QUESTION.starts_with(
            "Raven's login item starts Raven again when you log in. Keep Raven stopped until \
             you start it yourself? [y/N]"
        ));
        for yes in ["y", "Y", "yes", " YES "] {
            assert!(answer_is_yes(yes), "{yes}");
        }
        for no in ["", "n", "no", "ye", "yes please"] {
            assert!(!answer_is_yes(no), "{no}");
        }
    }

    #[test]
    fn the_passphrase_file_is_the_named_one_else_passfiles() {
        let tmp = tempfile::tempdir().unwrap();
        let home = tmp.path().join("home");
        let default = home.join(DEFAULT_PASSPHRASE_FILE);
        let named = tmp.path().join("pass");
        let os = |p: &Path| Some(p.as_os_str().to_owned());
        let saved = |env: Option<std::ffi::OsString>, home: Option<std::ffi::OsString>| {
            saved_passphrase_file(env, None, None, home)
        };
        assert_eq!(saved(os(&named), os(&home)), None);
        std::fs::create_dir_all(default.parent().unwrap()).unwrap();
        std::fs::write(&default, b"x").unwrap();
        assert_eq!(saved(os(&named), os(&home)), Some(default.clone()));
        assert_eq!(saved(Some("".into()), os(&home)), Some(default.clone()));
        std::fs::write(&named, b"x").unwrap();
        assert_eq!(saved(os(&named), os(&home)), Some(named.clone()));
        assert_eq!(saved(None, Some("home".into())), None);

        // Review D-lock-tui-3: the systemd credential, then the file Raven's
        // own login item names (any absolute path the installer took),
        // before PASSFILE's default; the variable still goes first.
        let credentials = tmp.path().join("credentials");
        std::fs::create_dir_all(&credentials).unwrap();
        let credential = credentials.join("raven-keystore-passphrase");
        let unit = tmp.path().join("custom").join("unit-pass");
        std::fs::create_dir_all(unit.parent().unwrap()).unwrap();
        std::fs::write(&unit, b"x").unwrap();
        assert_eq!(
            saved_passphrase_file(None, os(&credentials), Some(unit.clone()), os(&home)),
            Some(unit.clone()),
            "no credential there yet"
        );
        std::fs::write(&credential, b"x").unwrap();
        assert_eq!(
            saved_passphrase_file(None, os(&credentials), Some(unit.clone()), os(&home)),
            Some(credential)
        );
        assert_eq!(
            saved_passphrase_file(os(&named), os(&credentials), Some(unit.clone()), None),
            Some(named)
        );
        // A unit file that is not there, or a relative path: the default.
        let gone = tmp.path().join("gone");
        for unit in [gone, PathBuf::from("custom/unit-pass")] {
            assert_eq!(
                saved_passphrase_file(None, None, Some(unit), os(&home)),
                Some(default.clone())
            );
        }
    }

    /// Review D-lock-tui-3: a vault profile run by Raven's own systemd unit
    /// with a passphrase file the user's shell does not name (the installer
    /// took a custom path, as `Environment=` or as `LoadCredential=`).
    /// `raven lock` finds it through the unit, and its question says that
    /// the file still unlocks Raven.
    #[cfg(unix)]
    #[test]
    fn lock_finds_the_passphrase_file_raven_s_own_unit_names() {
        use node_control::Platform;
        let dir = marked_profile();
        let dd = std::fs::canonicalize(dir.path()).unwrap();
        let tmp = tempfile::tempdir().unwrap();
        let custom = tmp.path().join("secrets").join("raven-pass");
        std::fs::create_dir_all(custom.parent().unwrap()).unwrap();
        std::fs::write(&custom, b"x").unwrap();
        let home = tmp.path().join("home");
        for line in [
            format!(
                "Environment=\"RAVEN_KEYSTORE_PASSPHRASE_FILE={}\"",
                custom.display()
            ),
            format!(
                "LoadCredential=raven-keystore-passphrase:{}",
                custom.display()
            ),
        ] {
            let (env, log) = login_lab(Platform::Linux, &dd, tmp.path(), false);
            let unit = tmp.path().join("items").join(Platform::Linux.item_file());
            let text = std::fs::read_to_string(&unit).unwrap();
            let text = text.replace(
                "Restart=on-failure\n",
                &format!("Restart=on-failure\n{line}\n"),
            );
            std::fs::write(&unit, text).unwrap();
            // The shell names no file, and PASSFILE's default is not there.
            let var = |name: &str| (name == "HOME").then(|| home.clone().into_os_string());
            let found = profile_passphrase_file(&dd, Some(&env), &var);
            assert_eq!(found.as_deref(), Some(custom.as_path()), "{line}");
            let question = lock_question(true, found.as_deref());
            assert!(
                question.contains(&format!(
                    "Your passphrase is saved in a file on this computer ({}). Anyone who can \
                     read your files can unlock Raven with it.",
                    custom.display()
                )),
                "{question}"
            );
            // Without the unit's line the question has no such paragraph.
            assert_eq!(profile_passphrase_file(&dd, None, &var), None);
            // Reading the unit runs no tool.
            assert!(node_control::tests::calls(&log).is_empty());
        }
        // Another profile's unit names no file of this one.
        let other = marked_profile();
        let (env, _log) = login_lab(Platform::Linux, &dd, tmp.path(), false);
        let var = |_: &str| None;
        assert_eq!(
            profile_passphrase_file(other.path(), Some(&env), &var),
            None
        );
    }

    #[test]
    fn status_and_doctor_say_locked() {
        use raven_core::privacy::{self, LockState, LockedItem};
        let dir = marked_profile();
        let dd = dir.path();
        let none: Result<IpcResponse, String> = Err("raven-node is not running".into());
        assert_eq!(locked_status_line(dd, &none), None);
        assert_eq!(
            doctor_lock_line(privacy::lock_state(dd)),
            "lock: locked_by_user=0"
        );
        privacy::set_locked(dd, None).unwrap();
        assert_eq!(
            locked_status_line(dd, &none),
            Some("Raven is locked (stopped). Run `raven unlock` to start it again.")
        );
        let answered = Ok(IpcResponse::Status {
            v: IPC_VERSION,
            bridge: false,
            store: false,
            relay: false,
            forward_pending: 0,
            capabilities: Vec::new(),
            p2p: None,
            pid: Some(42),
            lan_listen: None,
            last_paths: Vec::new(),
            route_hints: None,
            unreachable: Vec::new(),
            egress: None,
            lan_listen_wanted: None,
            lan_bind_error: None,
            clock_skew: Vec::new(),
            unanswered: Vec::new(),
            at_rest: None,
            lan: None,
            security: None,
            nearby: None,
            tor: None,
            learning: None,
            locked: None,
            updates: None,
        });
        assert_eq!(locked_status_line(dd, &answered), None, "a node answers");
        // Lock v2 (P6.40): a node that runs locked says so first.
        let mut locked = answered.clone();
        if let Ok(IpcResponse::Status { locked: l, .. }) = &mut locked {
            *l = Some(true);
        }
        assert_eq!(
            locked_status_line(dd, &locked),
            Some(raven_core::privacy::LOCKED_V2_STATUS_LINE)
        );
        assert_eq!(
            doctor_lock_line(privacy::lock_state(dd)),
            "lock: locked_by_user=1"
        );
        assert_eq!(
            doctor_lock_line(LockState {
                locked_by_user: true,
                login_item: Some(LockedItem::Disabled),
                by_app: false,
            }),
            "lock: locked_by_user=1 login_item=disabled"
        );
    }

    #[cfg(unix)]
    #[test]
    fn lock_on_macos_always_boots_out_even_on_no() {
        use node_control::Platform;
        use raven_core::privacy::{lock_state, LockState, LockedItem};
        let dir = marked_profile();
        let dd = dir.path();
        let tmp = tempfile::tempdir().unwrap();
        let (env, log) = login_lab(Platform::MacOs, dd, tmp.path(), false);
        let mut asked = 0;
        let outcome = lock_profile(dd, &env, false, &mut || {
            asked += 1;
            false
        })
        .unwrap();
        assert_eq!(
            asked, 1,
            "asked once: Raven's own login item runs this profile"
        );
        assert_eq!(
            outcome,
            LockOutcome::Locked {
                notes: Vec::new(),
                lines: lock_result_lines(false, Some(false)),
            }
        );
        assert_eq!(
            node_control::tests::calls(&log),
            ["launchctl bootout gui/501/com.raven.raven-node"],
            "unloaded for the session even on no: KeepAlive would start it again"
        );
        assert_eq!(
            lock_state(dd),
            LockState {
                locked_by_user: true,
                login_item: Some(LockedItem::Unloaded),
                by_app: false,
            }
        );

        // The job was not loaded (bootout fails) and Raven is gone: locked,
        // and nothing is said about the failed bootout.
        let dir = marked_profile();
        let tmp = tempfile::tempdir().unwrap();
        let (env, log) = login_lab(Platform::MacOs, dir.path(), tmp.path(), true);
        let outcome = lock_profile(dir.path(), &env, false, &mut || false).unwrap();
        assert_eq!(
            outcome,
            LockOutcome::Locked {
                notes: Vec::new(),
                lines: lock_result_lines(false, Some(false)),
            }
        );
        assert_eq!(node_control::tests::calls(&log).len(), 1);

        // Another profile's item: never asked, never touched.
        let other = marked_profile();
        let outcome = lock_profile(other.path(), &env, false, &mut || panic!("not asked")).unwrap();
        assert_eq!(
            outcome,
            LockOutcome::Locked {
                notes: Vec::new(),
                lines: lock_result_lines(false, None),
            }
        );
        assert_eq!(
            node_control::tests::calls(&log).len(),
            1,
            "nothing more ran"
        );
        assert!(lock_state(other.path()).locked_by_user);
    }

    #[cfg(unix)]
    #[test]
    fn lock_disables_and_unlock_reenables_through_the_shims() {
        use node_control::Platform;
        use raven_core::privacy::{lock_state, LockState, LockedItem};
        for platform in [Platform::MacOs, Platform::Linux, Platform::Windows] {
            let dir = marked_profile();
            let dd = dir.path();
            let tmp = tempfile::tempdir().unwrap();
            let (env, log) = login_lab(platform, dd, tmp.path(), false);
            let outcome = lock_profile(dd, &env, true, &mut || true).unwrap();
            assert_eq!(
                outcome,
                LockOutcome::Locked {
                    notes: Vec::new(),
                    lines: lock_result_lines(true, Some(true)),
                },
                "{platform:?}"
            );
            assert_eq!(
                lock_state(dd),
                LockState {
                    locked_by_user: true,
                    login_item: Some(LockedItem::Disabled),
                    by_app: false,
                }
            );
            // Unlock turns the item back on and starts it; the fake tools
            // start nothing, so no node answers: unlock says so and keeps
            // the record for the next try (the lock itself is gone).
            let err = unlock_profile(
                dd,
                || Ok(env.clone()),
                |_| panic!("the login item starts Raven, not a send's start"),
                Duration::ZERO,
            )
            .unwrap_err();
            assert!(
                err.starts_with("Raven's login item did not start Raven within 0 s."),
                "{err}"
            );
            assert_eq!(
                lock_state(dd),
                LockState {
                    locked_by_user: false,
                    login_item: Some(LockedItem::Disabled),
                    by_app: false,
                }
            );
            let plist = tmp.path().join("items").join(platform.item_file());
            let want: Vec<String> = match platform {
                Platform::MacOs => vec![
                    "launchctl bootout gui/501/com.raven.raven-node".into(),
                    "launchctl disable gui/501/com.raven.raven-node".into(),
                    "launchctl enable gui/501/com.raven.raven-node".into(),
                    format!("launchctl bootstrap gui/501 {}", plist.display()),
                ],
                Platform::Linux => vec![
                    "systemctl --user stop raven-node.service".into(),
                    "systemctl --user disable --now raven-node.service".into(),
                    "systemctl --user enable --now raven-node.service".into(),
                ],
                Platform::Windows => vec![
                    "schtasks.exe /End /TN RavenNodeBridge".into(),
                    "schtasks.exe /Change /TN RavenNodeBridge /DISABLE".into(),
                    "schtasks.exe /Change /TN RavenNodeBridge /ENABLE".into(),
                    "schtasks.exe /Run /TN RavenNodeBridge".into(),
                ],
            };
            assert_eq!(node_control::tests::calls(&log), want, "{platform:?}");
        }
    }

    #[test]
    fn unlock_without_a_login_item_starts_raven_as_a_send_does() {
        use raven_core::privacy::{self, LockState, LockedItem};
        let dir = marked_profile();
        let dd = dir.path();
        privacy::set_locked(dd, None).unwrap();
        let mut started = 0;
        let notes = unlock_profile(
            dd,
            || panic!("no login item recorded: none is looked for"),
            |_| {
                started += 1;
                Ok(())
            },
            Duration::ZERO,
        )
        .unwrap();
        assert!(notes.is_empty());
        assert_eq!(started, 1);
        assert_eq!(privacy::lock_state(dd), LockState::default());

        // The item the lock turned off is gone (or runs another profile
        // now): forgotten, and Raven starts as a send starts it.
        privacy::set_locked(dd, Some(LockedItem::Disabled)).unwrap();
        let tmp = tempfile::tempdir().unwrap();
        let env =
            node_control::LoginEnv::lab(node_control::Platform::THIS, tmp.path(), tmp.path(), 501);
        unlock_profile(dd, || Ok(env), |_| Ok(()), Duration::ZERO).unwrap();
        assert_eq!(privacy::lock_state(dd), LockState::default());

        // A start that fails says why; the lock is gone all the same.
        privacy::set_locked(dd, None).unwrap();
        let err = unlock_profile(
            dd,
            || panic!("not looked for"),
            |_| Err("could not start".into()),
            Duration::ZERO,
        )
        .unwrap_err();
        assert_eq!(err, "could not start");
        assert!(!privacy::lock_state(dd).locked_by_user);
    }

    /// A node that answers but cannot be stopped from here (its Status
    /// names no pid): the lock is taken back and the user is told how.
    #[cfg(unix)]
    #[test]
    fn a_node_that_does_not_stop_is_not_locked() {
        use raven_core::privacy::lock_state;
        let dir = ipc_client::test_support::short_tempdir();
        let dd = dir.path();
        std::fs::write(dd.join(raven_core::BACKEND_MARKER_NAME), b"locked-file\n").unwrap();
        ipc_client::test_support::spawn_status_server(
            &raven_core::ipc::default_socket_path(dd),
            Vec::new,
        );
        let tmp = tempfile::tempdir().unwrap();
        let env =
            node_control::LoginEnv::lab(node_control::Platform::THIS, tmp.path(), tmp.path(), 501);
        match lock_profile(dd, &env, false, &mut || panic!("no login item")).unwrap() {
            LockOutcome::NotStopped(text) => {
                assert!(
                    text.starts_with(
                        "Raven is still running, so it isn't locked. Stop it \
                         yourself (pkill -f "
                    ),
                    "{text}"
                );
            }
            other => panic!("{other:?}"),
        }
        assert!(!lock_state(dd).locked_by_user, "the lock is taken back");

        // Review D-lock-tui-4: Raven's own login item runs this profile and
        // the user said to keep Raven stopped, but Raven still runs. The
        // item was only unloaded for this login session, never turned off:
        // it starts Raven at the next login, as before the lock. (Windows'
        // task, as the review found it: the node an app started is not the
        // task's, so the stop only advises.)
        let lab = tempfile::tempdir().unwrap();
        let (env, log) = login_lab(node_control::Platform::Windows, dd, lab.path(), false);
        match lock_profile(dd, &env, false, &mut || true).unwrap() {
            LockOutcome::NotStopped(text) => {
                assert!(text.starts_with("Raven is still running"), "{text}");
            }
            other => panic!("{other:?}"),
        }
        assert_eq!(
            node_control::tests::calls(&log),
            ["schtasks.exe /End /TN RavenNodeBridge"],
            "unloaded for this login session only, never turned off"
        );
        let state = lock_state(dd);
        assert!(!state.locked_by_user);
        assert_eq!(
            state.login_item,
            Some(raven_core::privacy::LockedItem::Unloaded),
            "`raven unlock` loads it again; nothing turned it off"
        );
    }

    /// Review D-lock-tui-4's other half: `raven lock` turns Raven's own
    /// login item off only once Raven is gone; and a lock after the app's
    /// UNLOCK left the item off says Raven is stopped (not "until you log
    /// in again"), whatever the answer.
    #[cfg(unix)]
    #[test]
    fn lock_turns_the_item_off_only_once_raven_is_gone() {
        use node_control::Platform;
        use raven_core::privacy::{lock_state, set_unlocked, LockedItem};
        let dir = marked_profile();
        let dd = dir.path();
        let tmp = tempfile::tempdir().unwrap();
        let (env, log) = login_lab(Platform::Linux, dd, tmp.path(), false);
        let outcome = lock_profile(dd, &env, false, &mut || true).unwrap();
        assert_eq!(
            outcome,
            LockOutcome::Locked {
                notes: Vec::new(),
                lines: lock_result_lines(false, Some(true)),
            }
        );
        assert_eq!(
            node_control::tests::calls(&log),
            [
                "systemctl --user stop raven-node.service",
                "systemctl --user disable --now raven-node.service",
            ]
        );
        assert_eq!(lock_state(dd).login_item, Some(LockedItem::Disabled));
        // The app's UNLOCK cleared the lock and left the item off; a new
        // lock answered no: the item is still off.
        set_unlocked(dd).unwrap();
        let outcome = lock_profile(dd, &env, false, &mut || false).unwrap();
        assert_eq!(
            outcome,
            LockOutcome::Locked {
                notes: Vec::new(),
                lines: lock_result_lines(false, Some(true)),
            }
        );
        assert_eq!(lock_result_lines(false, Some(true))[0], "Raven is stopped.");
    }

    // ── raven erase (privacy pack PP.16) ──

    /// A sealed lab profile `home/name` with [`seed_book`]'s contacts (the
    /// erase tests that use it are Unix-only).
    #[cfg(unix)]
    fn sealed_profile_in(home: &Path, name: &str) -> PathBuf {
        let dd = home.join(name);
        std::fs::create_dir_all(&dd).unwrap();
        std::fs::write(dd.join(raven_core::BACKEND_MARKER_NAME), b"locked-file\n").unwrap();
        seed_book(&dd);
        let report = raven_core::privacy::migrate_all(
            &dd,
            now_ms(),
            raven_core::at_rest::MigratePolicy::Allow,
        )
        .unwrap();
        assert_eq!(report.outcome, raven_core::privacy::MigrateOutcome::Sealed);
        std::fs::canonicalize(dd).unwrap()
    }

    /// Every file below `dir` with its bytes.
    #[cfg(unix)]
    fn tree_bytes(dir: &Path) -> std::collections::BTreeMap<PathBuf, Vec<u8>> {
        let mut out = std::collections::BTreeMap::new();
        let mut stack = vec![dir.to_path_buf()];
        while let Some(folder) = stack.pop() {
            for entry in std::fs::read_dir(&folder).into_iter().flatten().flatten() {
                let path = entry.path();
                if path.is_dir() {
                    stack.push(path);
                } else {
                    out.insert(path.clone(), std::fs::read(&path).unwrap_or_default());
                }
            }
        }
        out
    }

    #[test]
    fn paste_guard_and_non_tty_refusal() {
        let slow = Duration::from_millis(900);
        let fast = Duration::from_millis(40);
        let run = |answers: Vec<(&str, Duration)>| {
            let mut answers = answers.into_iter();
            let mut out = Vec::new();
            let yes = confirm_erase(&mut out, "Q? ", &mut || {
                answers.next().map(|(a, t)| (a.to_owned(), t))
            });
            (yes, String::from_utf8(out).unwrap())
        };
        assert_eq!(run(vec![("erase", slow)]), (true, "Q? ".to_owned()));
        assert!(run(vec![("  ERASE ", slow)]).0);
        // The same keys on a Persian keyboard layout (input tolerance only).
        assert!(run(vec![("\u{062b}\u{0642}\u{0634}\u{0633}\u{062b}", slow)]).0);
        // Pasted (or typed before the question): refused, the prompt again.
        let (yes, said) = run(vec![("erase", fast), ("erase", slow)]);
        assert!(yes);
        assert_eq!(said, format!("Q? {ERASE_PASTED}\n{ERASE_PROMPT}"));
        assert!(!run(vec![("erase", fast)]).0, "then EOF");
        assert!(!run(vec![("erase", fast); ERASE_PROMPT_TRIES + 1]).0);
        for no in ["", "y", "yes", "delete", "erase now", "erasee"] {
            assert!(!run(vec![(no, slow)]).0, "{no:?}");
        }
        assert!(!run(Vec::new()).0, "EOF is no");
        // The question is the UX copy's, the prompt at its end.
        let question = format!("{ERASE_TITLE} {ERASE_PARAGRAPH}");
        assert!(question.starts_with("Erase Raven from this computer? This deletes"));
        assert!(question.ends_with("pieces of old files may still be found."));
        assert_eq!(
            ERASE_NEEDS_TERMINAL,
            "raven erase needs a terminal: type erase to confirm."
        );
    }

    #[cfg(unix)]
    #[test]
    fn erase_refuses_while_the_node_still_answers() {
        if !lab_hist_key() {
            return;
        }
        let home = ipc_client::test_support::short_tempdir();
        let dd = sealed_profile_in(home.path(), "a");
        let (env, log) = login_lab(node_control::Platform::MacOs, &dd, home.path(), false);
        ipc_client::test_support::spawn_status_server(
            &raven_core::ipc::default_socket_path(&dd),
            Vec::new,
        );
        let before = tree_bytes(&dd);
        let mut said = Vec::new();
        let err = erase_profile(&dd, &env, &mut |w| said.push(w.to_owned()), &mut || {
            panic!("nothing is closed while Raven runs")
        })
        .unwrap_err();
        assert!(
            err.starts_with(
                "Raven is still running, so erase can't continue: stop it yourself (pkill -f "
            ) && err.ends_with("then run `raven erase` again. Nothing was erased."),
            "{err}"
        );
        assert_eq!(said, ["Stopping Raven..."]);
        // Only unloaded for the session: the item stays, nothing else ran.
        assert_eq!(
            node_control::tests::calls(&log),
            ["launchctl bootout gui/501/com.raven.raven-node"]
        );
        assert!(home
            .path()
            .join("items/com.raven.raven-node.plist")
            .exists());
        assert_eq!(tree_bytes(&dd), before, "nothing changed");
    }

    // ── raven privacy unseal | seal-now | rotate-meta (privacy pack PP.18) ──

    /// A node that answers and cannot be stopped from here (its Status names
